    ('f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Quiz — Diderot, 1805 — un dialogue explosif publié après tout le monde', 'Français', '1re', 'Le Neveu de Rameau, Denis Diderot', 'f6439069-5824-53c2-a03c-d074a1cbbe96'::uuid),
    ('8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Quiz — Ponge, 1942 — trente-deux objets, trente-deux poèmes', 'Français', '1re', 'Le Parti pris des choses, Francis Ponge', '8e32b372-a5f0-5754-9ab9-c177261f5ded'::uuid),
    ('ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Quiz — Marivaux, 1734-1735 — monter par les femmes', 'Français', '1re', 'Le paysan parvenu, Marivaux', '0b58371e-bc03-5fd4-8b2c-5bd093219090'::uuid),
    ('6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'Quiz — Balzac, 1835 — la pension Vauquer et la conquête de Paris', 'Français', '1re', 'Le Père Goriot, Honoré de Balzac', '57d574fd-4d5c-5cac-bf8c-7fc2191f3770'::uuid),
    ('eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'Quiz — Courteline — la saynète en quelques répliques', 'Français', '1re', 'Le Petit Malade, Georges Courteline', 'db5de51c-d77c-5714-bb02-a7cc63ae5630'::uuid),
    ('b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'Quiz — Kafka, 1925 — accusé sans savoir de quoi', 'Français', '1re', 'Le Procès, Franz Kafka', '2d84da7c-6219-5885-adc9-61c9f4cbb696'::uuid),
    ('eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Quiz — Tournier, 1970 — le mythe de l’ogre', 'Français', '1re', 'Le Roi des Aulnes, Michel Tournier', '04b8daac-a0d8-5d8b-9092-c57d31e886c1'::uuid),
    ('688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'Quiz — Ionesco, 1962 — apprendre à mourir en une heure trente', 'Français', '1re', 'Le Roi se meurt, Eugène Ionesco', 'b623e1a0-44b1-5aa3-839d-4a16c1dbd0bd'::uuid),
    ('aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'Quiz — Gautier, 1858 — l’Égypte ressuscitée par l’érudition', 'Français', '1re', 'Le Roman de la momie, Théophile Gautier', '20112df1-008d-50a9-88e2-8099c03ed318'::uuid),
    ('adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Quiz — Aragon, 1956 — une autobiographie en vers', 'Français', '1re', 'Le Roman inachevé, Louis Aragon', '52f393d5-e832-5464-92a0-e3784b86ce0b'::uuid),
    ('834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Quiz — Stendhal, 1830 — chronique de 1830', 'Français', '1re', 'Le Rouge et le Noir, Stendhal', '9b24d80f-5cde-5dd2-a10e-99c76e0da1bb'::uuid),
    ('6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Quiz — Molière, 1664-1669 — cinq ans de bataille contre les dévots', 'Français', '1re', 'Le Tartuffe, Molière', 'c06e4cdb-78e5-52a6-9e76-ffef61971370'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('9fde2290-001f-5b12-ac9f-fe30f077f1f8'::uuid, '7ea6cbae-8dee-504a-9e90-e91d7cf669be'::uuid, 'Que font les animaux au début du récit ?', 'mcq', '["Ils chassent le fermier et fondent leur propre ferme","Ils fuient dans la forêt","Ils obéissent à un nouveau maître","Ils construisent un moulin"]'::jsonb, 0, 'Sept commandements sont peints sur le mur de la grange.', 1),
    ('c94e64e6-5ce4-5f71-84e7-39e101c5eadf'::uuid, '7ea6cbae-8dee-504a-9e90-e91d7cf669be'::uuid, 'Quels deux cochons se disputent le pouvoir ?', 'mcq', '["Boule de Neige et Napoléon","Malabar et Douce","Sage l’Ancien et Brille-Babil","Jones et Napoléon"]'::jsonb, 0, 'Napoléon élève secrètement des chiens pour expulser son rival.', 2),
    ('7a807708-c4d3-52a4-bfa3-d21dad8bffd6'::uuid, '7ea6cbae-8dee-504a-9e90-e91d7cf669be'::uuid, 'Que devient Malabar, le cheval ?', 'mcq', '["Il est vendu à l’équarrisseur","Il devient chef de ferme","Il s’enfuit","Il est libéré"]'::jsonb, 0, 'Le travailleur dévoué est sacrifié par le régime qu’il a servi.', 3),
    ('18a283b5-e24b-56a7-af1e-dce3b1acd974'::uuid, '7ea6cbae-8dee-504a-9e90-e91d7cf669be'::uuid, 'Comment le dernier commandement est-il réécrit ?', 'mcq', '["« Tous les animaux sont égaux, mais certains sont plus égaux que d’autres »","« Le travail rend libre »","« Quatre pattes, oui ; deux pattes, non »","« Napoléon a toujours raison »"]'::jsonb, 0, 'La réécriture nocturne des lois est le cœur de la satire.', 4),
    ('a61b5c91-8699-5bc1-a45b-e302045b2066'::uuid, '7ea6cbae-8dee-504a-9e90-e91d7cf669be'::uuid, 'Quel événement historique l’apologue transpose-t-il ?', 'mcq', '["La révolution russe et sa confiscation par Staline","La Révolution française","La guerre d’Espagne","La révolution industrielle"]'::jsonb, 0, 'Orwell, socialiste, vise le totalitarisme, non la révolte.', 5),
    ('da56ee8e-5608-5e40-84db-086b07a647db'::uuid, '7ea6cbae-8dee-504a-9e90-e91d7cf669be'::uuid, 'À la fin, les cochons restent distincts des hommes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les animaux regardent par la fenêtre et ne peuvent plus les distinguer.', 6),
    ('5749b3f3-3801-55bc-b0c5-e129183875cb'::uuid, 'ddc68012-c656-5618-91a6-d79f7a80ef07'::uuid, 'Que veut Hector au début de la pièce ?', 'mcq', '["Empêcher la guerre en rendant Hélène","Venger l’enlèvement d’Hélène","Prendre le pouvoir à Troie","Partir en exil"]'::jsonb, 0, 'Il veut fermer les portes de la guerre.', 1),
    ('7b0157ed-2655-5988-98aa-95fc9dcf7f14'::uuid, 'ddc68012-c656-5618-91a6-d79f7a80ef07'::uuid, 'Qui pousse à la guerre dans Troie ?', 'mcq', '["Demokos, les vieillards et une partie de la cour","Andromaque","Ulysse","Cassandre"]'::jsonb, 0, 'Ils invoquent la beauté d’Hélène et la gloire.', 2),
    ('92e9aa41-e70e-5865-9ee6-ef1401614987'::uuid, 'ddc68012-c656-5618-91a6-d79f7a80ef07'::uuid, 'Que se passe-t-il entre Hector et Ulysse ?', 'mcq', '["Ils s’accordent lucidement pour éviter la guerre","Ils se battent en duel","Ils rompent les négociations","Ulysse refuse de parler"]'::jsonb, 0, 'Leur dialogue est un sommet du théâtre politique français.', 3),
    ('86908979-7d01-5d11-abe6-6a3cc4cd5360'::uuid, 'ddc68012-c656-5618-91a6-d79f7a80ef07'::uuid, 'Quel incident déclenche finalement la guerre ?', 'mcq', '["Le meurtre de Demokos, faussement imputé à Ajax","La fuite d’Hélène","Un oracle de Cassandre","L’arrivée de l’armée grecque"]'::jsonb, 0, 'La guerre arrive par les mots, la vanité et le hasard.', 4),
    ('7a6813b0-c6d0-514b-a807-af70336426b4'::uuid, 'ddc68012-c656-5618-91a6-d79f7a80ef07'::uuid, 'En quelle année la pièce a-t-elle été créée ?', 'mcq', '["1935","1914","1945","1925"]'::jsonb, 0, 'Entre l’arrivée d’Hitler au pouvoir et Munich.', 5),
    ('78633ff8-136f-5da5-b9a2-78ce51e255c2'::uuid, 'ddc68012-c656-5618-91a6-d79f7a80ef07'::uuid, 'Le titre annonce sincèrement que la guerre sera évitée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est ironique : le spectateur connaît d’avance l’issue.', 6),
    ('4ff50e11-b3c2-5f72-8e3a-b87baabc5caa'::uuid, '9cd9e470-642c-5084-af63-5838e1eca4e8'::uuid, 'À quel genre appartient cette pièce ?', 'mcq', '["La farce en un acte","La comédie de caractère en cinq actes","La comédie-ballet","La tragi-comédie"]'::jsonb, 0, 'Héritée du Moyen Âge et de la commedia dell’arte.', 1),
    ('abdf6222-bdc3-586f-94ea-3799a345d24a'::uuid, '9cd9e470-642c-5084-af63-5838e1eca4e8'::uuid, 'Quel ressort comique organise la pièce ?', 'mcq', '["Le renversement : l’enfermeur se retrouve enfermé","Un quiproquo sur les noms","Un déguisement","Une lettre interceptée"]'::jsonb, 0, 'Angélique feint de se tuer pour faire sortir son mari.', 2),
    ('a35ea87e-0721-53d3-be2f-a0afd9ed98ff'::uuid, '9cd9e470-642c-5084-af63-5838e1eca4e8'::uuid, 'Quel personnage type Molière introduit-il ici ?', 'mcq', '["Le docteur pédant qui parle sans répondre","Le valet rusé","Le père avare","Le militaire fanfaron"]'::jsonb, 0, 'Il le reprendra dans plusieurs pièces.', 3),
    ('c1499a7d-ce78-5778-be04-b2b242a9d674'::uuid, '9cd9e470-642c-5084-af63-5838e1eca4e8'::uuid, 'Quelle pièce ultérieure reprend cette intrigue ?', 'mcq', '["George Dandin","Le Misanthrope","Tartuffe","L’Avare"]'::jsonb, 0, 'Molière en fera une comédie en trois actes en 1668.', 4),
    ('e7f7ec3b-ff3b-5e11-a287-a4a2815cbbf9'::uuid, '9cd9e470-642c-5084-af63-5838e1eca4e8'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Par une réconciliation forcée devant Gorgibus","Par un divorce","Par la mort d’Angélique","Par la fuite du Barbouillé"]'::jsonb, 0, 'La farce ne cherche pas la vraisemblance du dénouement.', 5),
    ('c115c9e2-bf38-5b30-b6ea-faf236cc532e'::uuid, '9cd9e470-642c-5084-af63-5838e1eca4e8'::uuid, 'Molière a renié la farce une fois devenu auteur du roi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste le socle de tout son théâtre, jusqu’aux grandes comédies.', 6),
    ('edd8828b-9338-5deb-8050-cfff551e9218'::uuid, '25c3b9a9-5853-56ab-8b7b-c1c38a89d29f'::uuid, 'Qui est Pauline Quenu ?', 'mcq', '["Une orpheline riche, recueillie par ses cousins","La servante de la maison","La fille des Chanteau","Une voisine du village"]'::jsonb, 0, 'Sa fortune sera peu à peu dépensée par la famille.', 1),
    ('36eca657-67c0-567f-8623-91360859d6ca'::uuid, '25c3b9a9-5853-56ab-8b7b-c1c38a89d29f'::uuid, 'De quoi Lazare est-il hanté ?', 'mcq', '["La peur de la mort","La ruine","La mer","La religion"]'::jsonb, 0, 'Lecteur de Schopenhauer, il incarne le pessimisme.', 2),
    ('17eedda6-d278-5da6-88d3-da5ff986aa57'::uuid, '25c3b9a9-5853-56ab-8b7b-c1c38a89d29f'::uuid, 'Comment Pauline réagit-elle au mariage de Lazare avec Louise ?', 'mcq', '["Elle sacrifie son bonheur et sauve leur enfant à la naissance","Elle quitte la maison","Elle réclame son argent","Elle se venge"]'::jsonb, 0, 'Le don est sa manière d’exister.', 3),
    ('eccb549d-d254-5e91-a558-c2564c1af199'::uuid, '25c3b9a9-5853-56ab-8b7b-c1c38a89d29f'::uuid, 'Le titre du roman est-il ironique ?', 'mcq', '["Oui, et pas seulement : Pauline incarne une joie têtue","Non, le roman est joyeux","Oui, uniquement ironique","Il n’a pas de rapport avec le contenu"]'::jsonb, 0, 'Le don et l’acceptation s’opposent au pessimisme de Lazare.', 4),
    ('e3421e10-5961-5094-93e3-6d26c0756bc4'::uuid, '25c3b9a9-5853-56ab-8b7b-c1c38a89d29f'::uuid, 'Où se déroule le roman ?', 'mcq', '["À Bonneville, village normand battu par la mer","À Paris","Dans le Nord minier","En Provence"]'::jsonb, 0, 'La mer démolit peu à peu le village.', 5),
    ('fb00f44a-d467-5a1a-ba5f-c691707d590f'::uuid, '25c3b9a9-5853-56ab-8b7b-c1c38a89d29f'::uuid, 'Le roman appartient aux Rougon-Macquart.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le douzième volume du cycle.', 6),
    ('f93aa668-8e9b-5a49-ac61-47392bb3c2f0'::uuid, '0f2ec27b-38d3-5a55-991b-4dec07992f11'::uuid, 'Que vient faire l’élève chez le professeur ?', 'mcq', '["Préparer le « doctorat total »","Passer un examen","Demander du travail","Rendre un livre"]'::jsonb, 0, 'Elle sait additionner mais ne sait pas soustraire.', 1),
    ('b9d52f61-c496-53e7-8f5b-dccb191187f4'::uuid, '0f2ec27b-38d3-5a55-991b-4dec07992f11'::uuid, 'Comment le rapport de force évolue-t-il ?', 'mcq', '["Le professeur devient autoritaire, l’élève s’affaiblit et se tait","L’élève prend le pouvoir","Rien ne change","La bonne intervient dès le début"]'::jsonb, 0, 'Celui qui parle domine : c’est la thèse de la pièce.', 2),
    ('7157ddf1-a762-5ec9-89c6-3e279d6776d8'::uuid, '0f2ec27b-38d3-5a55-991b-4dec07992f11'::uuid, 'De quoi souffre l’élève à mesure que la leçon avance ?', 'mcq', '["D’un mal de dents de plus en plus violent","De maux de tête","De fièvre","De somnolence"]'::jsonb, 0, 'Le symptôme accompagne son effacement.', 3),
    ('0ca44b5d-b4dc-536a-868b-28bbcc59ec5c'::uuid, '0f2ec27b-38d3-5a55-991b-4dec07992f11'::uuid, 'Comment la leçon se termine-t-elle ?', 'mcq', '["Le professeur poignarde l’élève","L’élève s’enfuit","La leçon reprend le lendemain","La bonne renvoie l’élève"]'::jsonb, 0, 'C’est le quarantième meurtre de la journée.', 4),
    ('3e82d760-bb16-550e-82e5-8ce61ea27fa4'::uuid, '0f2ec27b-38d3-5a55-991b-4dec07992f11'::uuid, 'Que fait la bonne à la fin ?', 'mcq', '["Elle gronde, nettoie, lui passe un brassard et fait entrer l’élève suivante","Elle appelle la police","Elle s’enfuit","Elle console le professeur seulement"]'::jsonb, 0, 'Le brassard donne la lecture politique de la pièce.', 5),
    ('5821a456-82e1-562f-a6a6-c543c1161beb'::uuid, '0f2ec27b-38d3-5a55-991b-4dec07992f11'::uuid, 'La pièce dénonce le langage comme instrument de pouvoir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est même son sujet central, sous une mécanique comique implacable.', 6),
    ('049f2da5-ee55-532f-befa-4638da517cc1'::uuid, '0ce324f4-e5a2-531e-bc2f-5ba6bdb9f188'::uuid, 'Que désigne la « machine infernale » du titre ?', 'mcq', '["Le piège monté par les dieux pour anéantir Œdipe","Une arme de guerre","Le Sphinx","La ville de Thèbes"]'::jsonb, 0, 'Le prologue le dit : elle est « remontée à bloc ».', 1),
    ('b63d6648-3c70-51e0-bb2e-9b9b7dcd077e'::uuid, '0ce324f4-e5a2-531e-bc2f-5ba6bdb9f188'::uuid, 'Que fait le fantôme de Laïos à l’acte I ?', 'mcq', '["Il tente en vain d’avertir Jocaste","Il maudit Œdipe","Il révèle l’énigme","Il apparaît à Créon"]'::jsonb, 0, 'Son échec souligne l’inutilité des avertissements.', 2),
    ('2d2a27a0-6028-5b74-8c1f-84cc02bdab78'::uuid, '0ce324f4-e5a2-531e-bc2f-5ba6bdb9f188'::uuid, 'Comment Cocteau transforme-t-il l’épisode du Sphinx ?', 'mcq', '["Le Sphinx est une jeune fille lasse qui donne la réponse par amour","Œdipe tue le Sphinx sans parler","Le Sphinx est un dieu masculin","L’épisode est supprimé"]'::jsonb, 0, 'La victoire d’Œdipe n’en est pas une.', 3),
    ('699c7b2c-5c73-500b-97b3-5cac6ff97a71'::uuid, '0ce324f4-e5a2-531e-bc2f-5ba6bdb9f188'::uuid, 'Quel intervalle sépare l’acte III de l’acte IV ?', 'mcq', '["Dix-sept ans","Une nuit","Trois jours","Cinquante ans"]'::jsonb, 0, 'La peste éclate, et la vérité remonte.', 4),
    ('e05309a6-e7d4-5d95-952c-98b3da57ada8'::uuid, '0ce324f4-e5a2-531e-bc2f-5ba6bdb9f188'::uuid, 'Quel effet produit le ton familier employé par Cocteau ?', 'mcq', '["Le décalage avec l’issue tragique intensifie l’émotion","Il rend la pièce comique de bout en bout","Il annule le tragique","Il rend le mythe méconnaissable"]'::jsonb, 0, 'Le tragique tient au mécanisme, pas à la surprise.', 5),
    ('fec11bd8-aac8-51d7-b90d-65b68caa00a9'::uuid, '0ce324f4-e5a2-531e-bc2f-5ba6bdb9f188'::uuid, 'Le prologue cache l’issue de l’histoire au spectateur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’annonce d’emblée : tout le monde sait, sauf Œdipe.', 6),
    ('b22828e4-ff16-5b67-8ecb-eca83d1a03e8'::uuid, '2b651619-a1de-5b43-858e-ffc86b5a312f'::uuid, 'Pourquoi Germain part-il en voyage ?', 'mcq', '["Demander en mariage une veuve d’un village voisin","Vendre ses bœufs","Chercher du travail","Fuir son beau-père"]'::jsonb, 0, 'Il emmène malgré lui son fils et la jeune Marie.', 1),
    ('0cf8d294-02c4-55f9-a5f4-0e98ffc665e6'::uuid, '2b651619-a1de-5b43-858e-ffc86b5a312f'::uuid, 'Que se passe-t-il près de la mare au diable ?', 'mcq', '["Le brouillard les égare et ils passent la nuit dehors","Un accident mortel","Une rencontre avec des brigands","Un mariage clandestin"]'::jsonb, 0, 'La veillée rapproche Germain et Marie.', 2),
    ('6d492d49-064f-53ea-96a2-1d6079176830'::uuid, '2b651619-a1de-5b43-858e-ffc86b5a312f'::uuid, 'Que découvre Germain chez la veuve ?', 'mcq', '["Elle est entourée de prétendants qu’elle fait attendre","Elle est déjà mariée","Elle est très pauvre","Elle refuse de le recevoir"]'::jsonb, 0, 'Le voyage échoue — et réussit autrement.', 3),
    ('93449be2-09a4-5d70-aafd-be3d9c2af844'::uuid, '2b651619-a1de-5b43-858e-ffc86b5a312f'::uuid, 'À quel genre le roman appartient-il ?', 'mcq', '["Le roman champêtre","Le roman historique","Le roman épistolaire","Le roman gothique"]'::jsonb, 0, 'Avec La Petite Fadette et François le Champi.', 4),
    ('43d606ff-4248-5646-b37d-2adf7f4056cc'::uuid, '2b651619-a1de-5b43-858e-ffc86b5a312f'::uuid, 'Que défend George Sand dans ces romans ?', 'mcq', '["La dignité et l’intelligence des paysans","Le retour à la nature sauvage","La supériorité de la ville","L’art pour l’art"]'::jsonb, 0, 'Elle veut une littérature utile et fraternelle.', 5),
    ('1ace0d68-d8d7-5f40-8ead-89c324a5f645'::uuid, '2b651619-a1de-5b43-858e-ffc86b5a312f'::uuid, 'Le roman contient un appendice sur les coutumes du Berry.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un long texte sur les noces de campagne y est joint.', 6),
    ('89a32921-5d71-50a4-99c2-1749410f38c8'::uuid, '3c3c2c82-a20c-55dc-bed8-868a4c40880f'::uuid, 'Que trouve Euclion chez lui ?', 'mcq', '["Une marmite pleine d’or cachée par son grand-père","Un testament","Un trésor de guerre","Une lettre secrète"]'::jsonb, 0, 'La peur du vol organise toute la pièce.', 1),
    ('fd9e63c8-2094-5379-ab2d-1d743551ccad'::uuid, '3c3c2c82-a20c-55dc-bed8-868a4c40880f'::uuid, 'Quelle pièce française s’inspire directement de cette comédie ?', 'mcq', '["L’Avare de Molière","Le Misanthrope","Turcaret de Lesage","Le Légataire universel"]'::jsonb, 0, 'La marmite y devient la cassette d’Harpagon.', 2),
    ('e37d8d1d-90c9-5ce9-9df6-9d347a7d23ba'::uuid, '3c3c2c82-a20c-55dc-bed8-868a4c40880f'::uuid, 'Qui vole la marmite ?', 'mcq', '["L’esclave de Lyconide","Mégadore","Phédria","Un voisin"]'::jsonb, 0, 'Euclion croit alors devenir fou.', 3),
    ('efc33c2d-dcd0-5a3e-9e27-09027d7aa24b'::uuid, '3c3c2c82-a20c-55dc-bed8-868a4c40880f'::uuid, 'Que sait-on de la fin de la pièce ?', 'mcq', '["Le texte est perdu ; les résumés antiques indiquent qu’Euclion donne l’or en dot","Euclion meurt","La marmite n’est jamais retrouvée","La fin est parfaitement conservée"]'::jsonb, 0, 'Seuls des arguments anciens permettent de la reconstituer.', 4),
    ('3b995b6f-c0a4-58ad-a3c4-718a264d925d'::uuid, '3c3c2c82-a20c-55dc-bed8-868a4c40880f'::uuid, 'Quels types comiques la pièce met-elle en place ?', 'mcq', '["Le vieil avare, le jeune amoureux, l’esclave rusé","Le roi, la reine et le bouffon","Le soldat, le prêtre et le marchand","Le savant et l’ignorant"]'::jsonb, 0, 'Ils traverseront tout le théâtre occidental.', 5),
    ('fcf8a835-3b8d-51bb-a67d-e6d554c7b0f6'::uuid, '3c3c2c82-a20c-55dc-bed8-868a4c40880f'::uuid, 'Plaute écrivait en grec.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il écrivait en latin, en adaptant des modèles grecs.', 6),
    ('1ee38be5-ea50-5dd6-a2e0-91105a586810'::uuid, '7143849f-a190-5c06-833f-6d46c0fb5460'::uuid, 'Par quel événement le récit commence-t-il ?', 'mcq', '["Gregor se réveille métamorphosé en insecte","Gregor perd son emploi","Gregor tombe malade","Gregor rentre d’un long voyage"]'::jsonb, 0, 'Aucune explication ne sera jamais donnée.', 1),
    ('05dc6b19-47aa-53f7-8dd9-8d8b141c893a'::uuid, '7143849f-a190-5c06-833f-6d46c0fb5460'::uuid, 'Quelle est la première préoccupation de Gregor ?', 'mcq', '["Manquer son train et son travail","Sa santé","La réaction de sa sœur","Trouver un remède"]'::jsonb, 0, 'Le fantastique est posé, le reste est décrit avec une précision administrative.', 2),
    ('d84f8512-504f-52d1-b1fe-eb98ec38e8ab'::uuid, '7143849f-a190-5c06-833f-6d46c0fb5460'::uuid, 'Qui s’occupe d’abord de Gregor ?', 'mcq', '["Sa sœur Grete","Sa mère","Son père","La femme de ménage"]'::jsonb, 0, 'Elle finit par se lasser et par réclamer qu’on s’en débarrasse.', 3),
    ('69de1a91-f43e-509c-a55e-084f9ebf6d0d'::uuid, '7143849f-a190-5c06-833f-6d46c0fb5460'::uuid, 'Que fait le père à Gregor ?', 'mcq', '["Il le blesse d’un jet de pomme qui pourrit dans son dos","Il le chasse de la maison","Il le vend à un cirque","Il le soigne"]'::jsonb, 0, 'La blessure ne guérira pas.', 4),
    ('2e225518-5c79-52a3-9093-1ca86e4c5769'::uuid, '7143849f-a190-5c06-833f-6d46c0fb5460'::uuid, 'Comment la famille réagit-elle à la mort de Gregor ?', 'mcq', '["Elle est soulagée et part en promenade au soleil","Elle est accablée de douleur","Elle quitte la ville","Elle refuse d’y croire"]'::jsonb, 0, 'La dernière page est d’une cruauté tranquille.', 5),
    ('1ff63a77-33da-5549-97fd-46138aa673fd'::uuid, '7143849f-a190-5c06-833f-6d46c0fb5460'::uuid, 'Le récit explique la cause de la métamorphose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est posée comme un fait : c’est ce qui fait la force du texte.', 6),
    ('c8fe085e-1077-5c84-a5b6-56a10a97e035'::uuid, '0d825e6f-43b3-585f-8772-23b779ee51c7'::uuid, 'Quelle est la particularité formelle du roman ?', 'mcq', '["Il est écrit à la deuxième personne du pluriel","Il n’a pas de ponctuation","Il est écrit en vers","Il alterne cinq narrateurs"]'::jsonb, 0, 'Le « vous » installe le lecteur à la place du personnage.', 1),
    ('ce5476e2-adae-57f5-8414-36b5050a92e4'::uuid, '0d825e6f-43b3-585f-8772-23b779ee51c7'::uuid, 'Où se déroule l’action ?', 'mcq', '["Dans un train Paris-Rome, pendant vingt et une heures","Dans un bureau parisien","À Rome, en une journée","Sur un paquebot"]'::jsonb, 0, 'Unité de lieu et de temps, comme au théâtre classique.', 2),
    ('ab5528b6-0a7c-56e1-90a3-52639c79ba95'::uuid, '0d825e6f-43b3-585f-8772-23b779ee51c7'::uuid, 'Quel est le projet initial de Léon Delmont ?', 'mcq', '["Annoncer à sa maîtresse qu’il quitte sa femme pour elle","Vendre son entreprise","Fuir ses créanciers","Visiter Rome en touriste"]'::jsonb, 0, 'Il lui a trouvé un emploi à Paris.', 3),
    ('67821e2e-9230-5040-a11b-f0ab3ed7f82a'::uuid, '0d825e6f-43b3-585f-8772-23b779ee51c7'::uuid, 'Qu’est-ce qui se « modifie » au cours du trajet ?', 'mcq', '["Sa décision : il renonce à quitter sa femme","Son itinéraire","Son métier","Son identité"]'::jsonb, 0, 'Il comprend que Cécile n’existe pour lui que liée à Rome.', 4),
    ('6a290ddc-8f1b-5493-a0af-9164d1e848e3'::uuid, '0d825e6f-43b3-585f-8772-23b779ee51c7'::uuid, 'À quel mouvement le roman appartient-il ?', 'mcq', '["Le Nouveau Roman","Le surréalisme","L’existentialisme","Le naturalisme"]'::jsonb, 0, 'Il en est l’œuvre la plus célèbre auprès du grand public.', 5),
    ('ebbdbcd8-65ed-5931-addc-512cb7293400'::uuid, '0d825e6f-43b3-585f-8772-23b779ee51c7'::uuid, 'Le roman comporte de nombreuses péripéties extérieures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’unique événement est un changement d’avis.', 6),
    ('a59acca2-0e92-55b4-b2bd-7afce00d2d28'::uuid, 'a54913e7-fe8a-5308-abb5-a82f5d6a947d'::uuid, 'Que se passe-t-il à chaque vœu exaucé ?', 'mcq', '["La peau rétrécit et la vie de Raphaël raccourcit","La peau change de couleur","Raphaël vieillit d’un an","La peau se réchauffe"]'::jsonb, 0, 'Vouloir, c’est vivre ; vivre, c’est se consumer.', 1),
    ('cfadfa85-feef-51ea-8c1d-abd832d60951'::uuid, 'a54913e7-fe8a-5308-abb5-a82f5d6a947d'::uuid, 'Quels verbes usent la vie selon l’antiquaire ?', 'mcq', '["Vouloir et Pouvoir","Aimer et Croire","Savoir et Comprendre","Créer et Détruire"]'::jsonb, 0, 'Seul SAVOIR conserve, dit-il.', 2),
    ('6c17cce1-70b4-5831-ba8d-f8d23e36a5c3'::uuid, 'a54913e7-fe8a-5308-abb5-a82f5d6a947d'::uuid, 'Qui est Fœdora ?', 'mcq', '["La comtesse incapable d’aimer, « la femme sans cœur »","La mère de Raphaël","Une servante","La femme de l’antiquaire"]'::jsonb, 0, 'Elle incarne la société parisienne, séduisante et vide.', 3),
    ('a75c0b26-fd58-5148-8ec8-e6fb026a87eb'::uuid, 'a54913e7-fe8a-5308-abb5-a82f5d6a947d'::uuid, 'Comment Raphaël meurt-il ?', 'mcq', '["En désirant Pauline, qui l’aime","D’une maladie ordinaire","Noyé dans la Seine","Tué en duel"]'::jsonb, 0, 'Il n’a pas pu s’empêcher de désirer.', 4),
    ('1c639c15-eea7-5c63-85c6-669b818f1ee0'::uuid, 'a54913e7-fe8a-5308-abb5-a82f5d6a947d'::uuid, 'À quel ensemble de La Comédie humaine appartient le roman ?', 'mcq', '["Les Études philosophiques","Les Scènes de la vie parisienne","Les Études analytiques","Les Scènes de la vie privée"]'::jsonb, 0, 'Il expose une idée : la pensée et le désir usent la vie.', 5),
    ('e97afd12-649c-561e-a8da-83887232d02c'::uuid, 'a54913e7-fe8a-5308-abb5-a82f5d6a947d'::uuid, 'Le fantastique du roman se déroule dans un décor irréel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le Paris de 1830 y est décrit avec une précision documentaire.', 6),
    ('a3dac6c4-c59d-53ef-84a1-c1015f49a89b'::uuid, '6de6c7f8-bf0c-5e90-a668-dd13b89c6ddc'::uuid, 'Dans quelle ville se déroule le roman ?', 'mcq', '["Oran","Alger","Marseille","Constantine"]'::jsonb, 0, 'La ville est fermée quand l’épidémie est reconnue.', 1),
    ('bce7c78f-f189-51ff-94e1-078fb057d049'::uuid, '6de6c7f8-bf0c-5e90-a668-dd13b89c6ddc'::uuid, 'Qui est le narrateur, révélé à la fin ?', 'mcq', '["Le docteur Rieux","Tarrou","Grand","Rambert"]'::jsonb, 0, 'Il a écrit une chronique de l’épidémie.', 2),
    ('5b8aa0f2-00d2-51fd-9e73-30e1fca48f76'::uuid, '6de6c7f8-bf0c-5e90-a668-dd13b89c6ddc'::uuid, 'Que décide Rambert ?', 'mcq', '["Rester pour lutter, au lieu de rejoindre la femme qu’il aime","Fuir la ville","Écrire un article accusateur","Se cacher chez Cottard"]'::jsonb, 0, 'Son évolution est l’un des fils moraux du roman.', 3),
    ('2f83cb94-fdf4-551c-8649-9a3b2e9d507f'::uuid, '6de6c7f8-bf0c-5e90-a668-dd13b89c6ddc'::uuid, 'Qu’est-ce qui fait changer le discours du père Paneloux ?', 'mcq', '["La mort atroce d’un enfant","La fermeture des églises","La guérison de Rieux","Le départ de Rambert"]'::jsonb, 0, 'Le châtiment divin ne peut plus expliquer l’innocent qui souffre.', 4),
    ('3ac55333-599f-5acc-ab16-58e23b5ed29f'::uuid, '6de6c7f8-bf0c-5e90-a668-dd13b89c6ddc'::uuid, 'Quel avertissement clôt le roman ?', 'mcq', '["Le bacille de la peste ne meurt ni ne disparaît jamais","La ville sera détruite","Rieux quitte Oran","Cottard sera jugé"]'::jsonb, 0, 'La vigilance vaut pour tous les fléaux, y compris politiques.', 5),
    ('fc461a53-26a0-5695-ac8d-cd5c31403e93'::uuid, '6de6c7f8-bf0c-5e90-a668-dd13b89c6ddc'::uuid, 'Le roman célèbre l’héroïsme exceptionnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Il ne s’agit pas d’héroïsme, il s’agit d’honnêteté » : Camus valorise le travail obstiné.', 6),
    ('2b81195b-d21e-5c2e-a82c-e3b43b5e8b0a'::uuid, '9cb9952a-4b1a-5950-8319-cc24c327df4f'::uuid, 'Qui sont Landry et Sylvinet ?', 'mcq', '["Deux frères jumeaux inséparables","Deux cousins rivaux","Les frères de Fadette","Deux fermiers voisins"]'::jsonb, 0, 'Leur séparation rend Sylvinet malade de jalousie.', 1),
    ('e4ead955-4c5c-561f-bef8-819f64bdf9ef'::uuid, '9cb9952a-4b1a-5950-8319-cc24c327df4f'::uuid, 'Pourquoi le village prend-il Fadette pour une sorcière ?', 'mcq', '["Elle est pauvre, moqueuse et élevée par une grand-mère guérisseuse","Elle jette réellement des sorts","Elle vient d’un autre pays","Elle refuse d’aller à l’église"]'::jsonb, 0, 'Le regard des autres fabrique la sorcière.', 2),
    ('916663b5-c1da-57bd-bbc6-67dc353a675e'::uuid, '9cb9952a-4b1a-5950-8319-cc24c327df4f'::uuid, 'Que fait Fadette pour Sylvinet ?', 'mcq', '["Elle le soigne de sa jalousie maladive","Elle l’épouse","Elle le dénonce","Elle l’éloigne du village"]'::jsonb, 0, 'Sa connaissance des plantes et des âmes le sauve.', 3),
    ('1cc7c510-3eb7-5509-a37a-2c95d23b97a1'::uuid, '9cb9952a-4b1a-5950-8319-cc24c327df4f'::uuid, 'Quel événement personnel change la situation de Fadette ?', 'mcq', '["Un héritage inattendu","Un mariage arrangé","Un départ pour la ville","La mort de Landry"]'::jsonb, 0, 'Elle acquiert aussi les manières que le village exigeait.', 4),
    ('53982e1c-85d0-52f2-b818-1a2c53295721'::uuid, '9cb9952a-4b1a-5950-8319-cc24c327df4f'::uuid, 'Dans quel contexte George Sand écrit-elle ce roman ?', 'mcq', '["Après l’échec de la révolution de 1848","Pendant la Restauration","Sous le Second Empire finissant","Avant 1830"]'::jsonb, 0, 'Elle veut parler d’autre chose que de politique, sans renier ses valeurs.', 5),
    ('aee2e9ed-4d11-55ec-8c11-460104dbe2b6'::uuid, '9cb9952a-4b1a-5950-8319-cc24c327df4f'::uuid, 'Le roman appartient aux romans champêtres de Sand.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec La Mare au diable et François le Champi.', 6),
    ('ffc2e8b5-3315-592b-84db-a02adba04a73'::uuid, '287d0577-7347-576f-ab7f-5999e6592cb3'::uuid, 'Pourquoi Alissa refuse-t-elle d’épouser Jérôme ?', 'mcq', '["Elle croit que leur bonheur les détournerait de Dieu","Elle en aime un autre","Sa famille s’y oppose","Elle est malade"]'::jsonb, 0, 'La « porte étroite » de l’Évangile lui sert de justification.', 1),
    ('bff0fbe5-c07f-538d-8bca-1238e566be56'::uuid, '287d0577-7347-576f-ab7f-5999e6592cb3'::uuid, 'Que révèle le journal d’Alissa ?', 'mcq', '["Qu’elle l’a aimé jusqu’au bout et a souffert de son sacrifice","Qu’elle ne l’a jamais aimé","Qu’elle aimait Juliette","Qu’elle projetait de fuir"]'::jsonb, 0, 'Sa découverte retourne toute la lecture du récit.', 2),
    ('bc5860b6-ea97-598a-8bd9-2989d6b954a6'::uuid, '287d0577-7347-576f-ab7f-5999e6592cb3'::uuid, 'Quel récit de Gide forme le pendant de celui-ci ?', 'mcq', '["L’Immoraliste","Les Faux-Monnayeurs","Les Caves du Vatican","Isabelle"]'::jsonb, 0, 'L’un montre l’excès de liberté, l’autre l’excès de vertu.', 3),
    ('11e76137-c5f2-581d-a917-7081fbc8c827'::uuid, '287d0577-7347-576f-ab7f-5999e6592cb3'::uuid, 'Comment Alissa meurt-elle ?', 'mcq', '["Seule, dans une maison de santé","Au couvent","Chez elle, entourée des siens","En voyage"]'::jsonb, 0, 'Le sacrifice ne mène à aucune consolation.', 4),
    ('8a32bd44-5f9f-500a-a478-d7017290f60b'::uuid, '287d0577-7347-576f-ab7f-5999e6592cb3'::uuid, 'Que met Gide en cause dans ce récit ?', 'mcq', '["Une religion qui fait du renoncement une valeur en soi","La foi en général","Le mariage bourgeois","L’éducation des filles seulement"]'::jsonb, 0, 'Il écrit depuis l’intérieur du protestantisme rigoriste où il a grandi.', 5),
    ('9f64923a-dea9-55a8-b10c-7c2c2674a476'::uuid, '287d0577-7347-576f-ab7f-5999e6592cb3'::uuid, 'Le récit est raconté uniquement par Jérôme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le journal d’Alissa vient en contrepoint et corrige tout ce qui précède.', 6),
    ('63296082-51f2-5302-aff5-0728c78e4a29'::uuid, 'e91aa8dc-c84f-5059-9975-f8b422f74d3c'::uuid, 'Quelle scène rend le roman célèbre ?', 'mcq', '["L’aveu de la princesse à son mari","Le duel de Nemours","Le bal du Louvre","La mort du roi"]'::jsonb, 0, 'Nemours, caché, entend tout : le procédé est audacieux.', 1),
    ('b6cfb809-4131-564e-bc4f-f8e1397732f0'::uuid, 'e91aa8dc-c84f-5059-9975-f8b422f74d3c'::uuid, 'Comment le roman a-t-il été publié ?', 'mcq', '["Anonymement, en 1678","Sous le nom de La Rochefoucauld","À titre posthume","En feuilleton"]'::jsonb, 0, 'L’anonymat protégeait une femme de lettres.', 2),
    ('2311e761-d46d-5738-8ece-09daed318364'::uuid, 'e91aa8dc-c84f-5059-9975-f8b422f74d3c'::uuid, 'De quoi meurt le prince de Clèves ?', 'mcq', '["De jalousie et de chagrin","D’une blessure de tournoi","D’une épidémie","Assassiné"]'::jsonb, 0, 'Il croit sa femme coupable.', 3),
    ('50f52e59-a54e-5039-80bc-deeb50b8358c'::uuid, 'e91aa8dc-c84f-5059-9975-f8b422f74d3c'::uuid, 'Que fait la princesse une fois veuve ?', 'mcq', '["Elle refuse d’épouser Nemours et se retire","Elle l’épouse aussitôt","Elle part à l’étranger","Elle entre immédiatement au couvent"]'::jsonb, 0, 'Devoir envers le mort et défiance envers la durée de la passion.', 4),
    ('480b1856-eab1-5a2c-9a5a-915e0d99b986'::uuid, 'e91aa8dc-c84f-5059-9975-f8b422f74d3c'::uuid, 'Qu’est-ce qui fait la nouveauté du roman ?', 'mcq', '["L’analyse des mouvements intérieurs plutôt que l’action","Le récit à la première personne","Le mélange des genres","La longueur des descriptions"]'::jsonb, 0, 'D’où l’expression « roman d’analyse ».', 5),
    ('6105eae1-2f28-5860-b47b-c04ff8a72437'::uuid, 'e91aa8dc-c84f-5059-9975-f8b422f74d3c'::uuid, 'La cour est présentée comme un lieu de sincérité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un système d’observation et de calcul où la sincérité est presque impossible.', 6),
    ('0091af27-292a-59f2-b9c2-65221177580e'::uuid, '2b8f6fdf-deb6-58a1-8756-bb80e737bf85'::uuid, 'Dans quel contexte historique se déroule le récit ?', 'mcq', '["Les guerres de religion","La Fronde","Le règne de Louis XIV","La Révolution"]'::jsonb, 0, 'La Saint-Barthélemy intervient dans le dénouement.', 1),
    ('43c49969-d394-5167-8a83-ff8d9b01bd61'::uuid, '2b8f6fdf-deb6-58a1-8756-bb80e737bf85'::uuid, 'Qui est le comte de Chabannes ?', 'mcq', '["Le confident loyal de la princesse, secrètement amoureux d’elle","Le frère du duc de Guise","Le père de la princesse","Un prêtre"]'::jsonb, 0, 'Il se sacrifiera pour la sauver.', 2),
    ('ea0ba12e-3118-5eac-bf23-1dcea98b49a4'::uuid, '2b8f6fdf-deb6-58a1-8756-bb80e737bf85'::uuid, 'Que fait Chabannes quand le prince surprend Guise ?', 'mcq', '["Il se laisse prendre pour l’amant","Il dénonce Guise","Il s’enfuit","Il défie le prince en duel"]'::jsonb, 0, 'Chassé, il sera tué pendant la Saint-Barthélemy.', 3),
    ('e4f5a72a-1c34-5fa0-9dae-38b762dea953'::uuid, '2b8f6fdf-deb6-58a1-8756-bb80e737bf85'::uuid, 'Que devient le duc de Guise ?', 'mcq', '["Il épouse une autre femme par ambition","Il meurt en duel","Il enlève la princesse","Il entre dans les ordres"]'::jsonb, 0, 'La princesse est abandonnée de tous.', 4),
    ('3ac619cf-4090-5a35-b1ed-04b2f72f2a2d'::uuid, '2b8f6fdf-deb6-58a1-8756-bb80e737bf85'::uuid, 'Quel roman ultérieur cette nouvelle annonce-t-elle ?', 'mcq', '["La Princesse de Clèves","Manon Lescaut","Les Liaisons dangereuses","La Nouvelle Héloïse"]'::jsonb, 0, 'Même cadre de cour, même conflit, même issue.', 5),
    ('4dc8c297-101c-563e-bfcd-1c0ac3733802'::uuid, '2b8f6fdf-deb6-58a1-8756-bb80e737bf85'::uuid, 'La nouvelle a été publiée sous le nom de son autrice.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle paraît anonymement en 1662.', 6),
    ('735f8031-a21b-5e3d-87c6-8ab36ea3a68b'::uuid, 'ea6686f6-a33a-5361-91d5-782ae6d98eba'::uuid, 'Qu’est-ce qui met « la puce à l’oreille » de Raymonde ?', 'mcq', '["Une paire de bretelles renvoyée d’un hôtel","Une lettre anonyme reçue","Un parfum inconnu","Un témoin"]'::jsonb, 0, 'Elle organise alors un faux rendez-vous pour confondre son mari.', 1),
    ('027b5252-96f7-5cce-8165-3af085756b35'::uuid, 'ea6686f6-a33a-5361-91d5-782ae6d98eba'::uuid, 'Qui va au rendez-vous à la place de Chandebise ?', 'mcq', '["Son ami Tournel","Son neveu Camille","Le docteur Finache","Homenidès"]'::jsonb, 0, 'Chandebise croit à une méprise et lui cède la place.', 2),
    ('a629cc8b-4815-5447-9e8e-ef026396da27'::uuid, 'ea6686f6-a33a-5361-91d5-782ae6d98eba'::uuid, 'Qui est Poche ?', 'mcq', '["Le garçon d’hôtel ivrogne, sosie parfait de Chandebise","Le patron de l’hôtel","Un policier","Le valet des Chandebise"]'::jsonb, 0, 'Le sosie est le moteur des quiproquos.', 3),
    ('98a38e4b-1116-5d46-9396-28f1577a1a81'::uuid, 'ea6686f6-a33a-5361-91d5-782ae6d98eba'::uuid, 'Quelle particularité a le neveu Camille ?', 'mcq', '["Il parle sans consonnes","Il est sourd","Il ne parle qu’espagnol","Il bégaie"]'::jsonb, 0, 'Chaque défaut a une fonction dans la mécanique comique.', 4),
    ('daa23150-da7c-5997-a2a4-98e3d5938469'::uuid, 'ea6686f6-a33a-5361-91d5-782ae6d98eba'::uuid, 'Comment se caractérise la construction de Feydeau ?', 'mcq', '["Une horlogerie où chaque objet et chaque détail sert","Une improvisation libre","Une succession de tableaux sans lien","Une intrigue psychologique"]'::jsonb, 0, 'Trois actes : exposition, machine infernale, retour à l’ordre.', 5),
    ('f43d3b6e-0c84-5c7e-864a-3ad5ddb155b1'::uuid, 'ea6686f6-a33a-5361-91d5-782ae6d98eba'::uuid, 'Le vaudeville se termine généralement par un bouleversement définitif de l’ordre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il revient toujours à l’ordre initial, le malentendu effacé.', 6),
    ('8ee272f5-2d07-5f19-8eb0-07ee78a13494'::uuid, '6259b80f-dbe2-56be-9614-7292b1c07a8c'::uuid, 'Que publie Ponge dans cette œuvre ?', 'mcq', '["Ses brouillons et ses reprises, datés","Des poèmes achevés","Un traité de poétique","Des souvenirs d’enfance"]'::jsonb, 0, 'Le poème devient un processus, non un résultat.', 1),
    ('01109e28-9640-5c77-b5f9-eebfd3b34b53'::uuid, '6259b80f-dbe2-56be-9614-7292b1c07a8c'::uuid, 'Quels objets Ponge choisit-il ?', 'mcq', '["Des objets modestes : pin, œillet, guêpe, mimosa","Des monuments","Des paysages grandioses","Des figures mythologiques"]'::jsonb, 0, 'Le minuscule est une prise de position contre le lyrisme du grandiose.', 2),
    ('ed07c7b3-ee52-5b50-843b-37b2b506f5eb'::uuid, '6259b80f-dbe2-56be-9614-7292b1c07a8c'::uuid, 'Que refuse Ponge dans sa description ?', 'mcq', '["Humaniser les choses et en faire le miroir de ses sentiments","Les nommer précisément","Consulter le dictionnaire","Les observer"]'::jsonb, 0, 'C’est le contraire du paysage romantique.', 3),
    ('fd553aad-433d-5404-b441-86d53c66dfb9'::uuid, '6259b80f-dbe2-56be-9614-7292b1c07a8c'::uuid, 'Que désigne la « rage » du titre ?', 'mcq', '["L’acharnement à reprendre un texte qui échoue","La colère politique","La violence de la nature","La haine du lecteur"]'::jsonb, 0, 'L’échec est intégré à l’œuvre : il en est le sujet.', 4),
    ('2796dbca-fa6e-58a2-9754-996b38ab4908'::uuid, '6259b80f-dbe2-56be-9614-7292b1c07a8c'::uuid, 'Quel outil accompagne son écriture ?', 'mcq', '["Le dictionnaire, notamment le Littré","Le carnet de voyage","L’appareil photo","Le traité de versification"]'::jsonb, 0, 'Étymologies et définitions successives sont des matériaux du poème.', 5),
    ('c198b9f5-56c1-5048-9e2e-81d7f1ea2540'::uuid, '6259b80f-dbe2-56be-9614-7292b1c07a8c'::uuid, 'Ponge publie ici des textes définitifs et polis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des carnets de travail, avec ratures, dates et contradictions.', 6),
    ('707a471e-81fa-5b2c-a5c4-951196a74973'::uuid, 'e8b6a0b1-062d-5406-847d-7c69922027ec'::uuid, 'Quel événement historique le roman raconte-t-il ?', 'mcq', '["Le massacre de la Saint-Barthélemy, en 1572","La Fronde","La Ligue et l’assassinat d’Henri III","La révocation de l’édit de Nantes"]'::jsonb, 0, 'Il suit de six jours le mariage de Margot et d’Henri de Navarre.', 1),
    ('8072bbc8-8c27-5ac9-bb94-f8f0cecc86b4'::uuid, 'e8b6a0b1-062d-5406-847d-7c69922027ec'::uuid, 'Qui est La Mole ?', 'mcq', '["Un gentilhomme protestant sauvé et aimé par Margot","Le frère du roi","Un capitaine des gardes catholique","Le médecin de Catherine"]'::jsonb, 0, 'Il sera exécuté avec son ami Coconnas.', 2),
    ('77458453-fece-52bf-8b43-113a0c9a3c00'::uuid, 'e8b6a0b1-062d-5406-847d-7c69922027ec'::uuid, 'Quel poison célèbre intervient dans l’intrigue ?', 'mcq', '["Un livre empoisonné destiné à Henri de Navarre","Une bague","Un vin de messe","Un gant"]'::jsonb, 0, 'C’est Charles IX qui en meurt : ressort romanesque typique de Dumas.', 3),
    ('c83d4a16-60f8-54fd-befc-8dcde9a7288c'::uuid, 'e8b6a0b1-062d-5406-847d-7c69922027ec'::uuid, 'Avec qui Dumas a-t-il écrit ce roman ?', 'mcq', '["Auguste Maquet","Gérard de Nerval","Eugène Sue","Paul Meurice"]'::jsonb, 0, 'Maquet a collaboré à la plupart des grands romans de Dumas.', 4),
    ('b57ca57f-eecd-5b96-aa92-b629a2611355'::uuid, 'e8b6a0b1-062d-5406-847d-7c69922027ec'::uuid, 'Quelle est la méthode revendiquée par Dumas ?', 'mcq', '["Violer l’Histoire à condition de lui faire de beaux enfants","Respecter scrupuleusement les sources","Écrire sans documentation","Réécrire les chroniques mot à mot"]'::jsonb, 0, 'Personnages réels, événements attestés, ressorts romanesques ajoutés.', 5),
    ('a0f95334-2eab-5723-a176-3b1a2b2e4fe0'::uuid, 'e8b6a0b1-062d-5406-847d-7c69922027ec'::uuid, 'Margot emporte la tête de son amant après l’exécution.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La scène, reprise de la légende, a marqué les lecteurs.', 6),
    ('9601ca61-5156-5ad3-aa87-5117e9410a4b'::uuid, '021bc55d-c379-54f5-b201-59c692d136a4'::uuid, 'Qui est Gertrude ?', 'mcq', '["Une jeune orpheline aveugle recueillie par le pasteur","La fille du pasteur","Une musicienne de passage","La femme de Jacques"]'::jsonb, 0, 'Le pasteur entreprend son éducation et tient un journal.', 1),
    ('f1a95526-1e7e-5ac8-90ad-809b19c760f5'::uuid, '021bc55d-c379-54f5-b201-59c692d136a4'::uuid, 'Quelle forme prend le récit ?', 'mcq', '["Le journal du pasteur, en deux cahiers","Un récit à la troisième personne","Des lettres échangées","Un dialogue"]'::jsonb, 0, 'Le journal se retourne progressivement contre son auteur.', 2),
    ('2f5efec6-02f5-5b24-88ec-df446825fd5d'::uuid, '021bc55d-c379-54f5-b201-59c692d136a4'::uuid, 'Que cache le pasteur dans sa description du monde ?', 'mcq', '["Le mal et le péché","Sa fortune","L’existence de son fils","La musique"]'::jsonb, 0, 'Il fabrique pour Gertrude un monde harmonieux et faux.', 3),
    ('6215a5f7-43bc-5163-9e10-8c6bb2ad8fc0'::uuid, '021bc55d-c379-54f5-b201-59c692d136a4'::uuid, 'Que découvre Gertrude après l’opération ?', 'mcq', '["Qu’elle aimait Jacques et qu’elle a fait souffrir toute une famille","Que le pasteur l’a trompée financièrement","Qu’elle est riche","Qu’elle n’aime personne"]'::jsonb, 0, 'Elle se jette alors dans la rivière.', 4),
    ('af604ec9-e934-5c79-9cc8-dcb333c8e068'::uuid, '021bc55d-c379-54f5-b201-59c692d136a4'::uuid, 'Pourquoi le titre est-il ironique ?', 'mcq', '["C’est le pasteur, non l’aveugle, qui ne voit rien","Il n’y a pas de musique dans le récit","La symphonie n’est jamais écoutée","Il n’y a pas de pasteur"]'::jsonb, 0, 'Gide vise une lecture complaisante de l’Évangile.', 5),
    ('83c97a6f-6bea-58d9-8315-88444c6d9d3b'::uuid, '021bc55d-c379-54f5-b201-59c692d136a4'::uuid, 'Le pasteur reconnaît d’emblée son amour pour Gertrude.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le nie et le déguise en charité : c’est le cœur du récit.', 6),
    ('33b7a989-d771-56dd-ba01-3b253da5d77a'::uuid, '87ed635c-f9d4-51cc-b353-5c3d9871f4b8'::uuid, 'Qui est Madame Rosa ?', 'mcq', '["Une ancienne prostituée juive rescapée d’Auschwitz, qui garde des enfants","La mère de Momo","Une infirmière","La concierge de l’immeuble"]'::jsonb, 0, 'Elle vit au sixième étage sans ascenseur, à Belleville.', 1),
    ('43aace98-3261-51f0-be10-b3eb6e53622e'::uuid, '87ed635c-f9d4-51cc-b353-5c3d9871f4b8'::uuid, 'Quelle est la particularité de la narration ?', 'mcq', '["Elle est portée par la voix de Momo, en français fautif","Elle est écrite à la troisième personne","Elle alterne plusieurs narrateurs","Elle est écrite en vers"]'::jsonb, 0, 'Mots déformés, humour et gravité mêlés.', 2),
    ('94de32a0-f492-5086-91ac-ade219357675'::uuid, '87ed635c-f9d4-51cc-b353-5c3d9871f4b8'::uuid, 'Que redoute Madame Rosa à la fin de sa vie ?', 'mcq', '["L’hôpital et l’acharnement thérapeutique","La police","La solitude seulement","De perdre son argent"]'::jsonb, 0, 'Momo l’aide à descendre dans son « trou juif ».', 3),
    ('61376e46-1261-5662-b1e0-6e5a13435eb4'::uuid, '87ed635c-f9d4-51cc-b353-5c3d9871f4b8'::uuid, 'Quel prix le roman a-t-il obtenu ?', 'mcq', '["Le prix Goncourt 1975","Le Renaudot","Le prix Femina","Le Médicis"]'::jsonb, 0, 'Sous le pseudonyme d’Émile Ajar.', 4),
    ('5acf7a08-e70d-58fb-ac4d-999f50a68dee'::uuid, '87ed635c-f9d4-51cc-b353-5c3d9871f4b8'::uuid, 'Quelle supercherie littéraire est liée à ce livre ?', 'mcq', '["Émile Ajar était Romain Gary, déjà goncourisé en 1956","Le roman avait été écrit par un autre auteur","Le manuscrit était un plagiat","Le prix a été retiré"]'::jsonb, 0, 'La vérité fut révélée après son suicide, en 1980.', 5),
    ('e5e02026-e857-5aab-b391-681e6d4a585b'::uuid, '87ed635c-f9d4-51cc-b353-5c3d9871f4b8'::uuid, 'Le roman se déroule dans un quartier bourgeois de Paris.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se déroule à Belleville, dans le Paris populaire et immigré des années 1970.', 6),
    ('b7904682-2414-5fff-be9f-edd5b733f875'::uuid, 'e9fdaf0b-e8be-54da-8c89-f4c24aefddd5'::uuid, 'Qui empêche le mariage du comte et de Rosine ?', 'mcq', '["Le docteur Bartholo, son tuteur, qui veut l’épouser","Le père de Rosine","Bazile seul","Figaro"]'::jsonb, 0, 'Il la surveille jour et nuit pour garder sa dot.', 1),
    ('0474943b-46c7-555a-bfb4-3e7e1d4fb112'::uuid, 'e9fdaf0b-e8be-54da-8c89-f4c24aefddd5'::uuid, 'Quel est le métier de Figaro dans cette pièce ?', 'mcq', '["Barbier et « factotum de la ville »","Valet du comte","Notaire","Maître de musique"]'::jsonb, 0, 'Il deviendra valet du comte dans Le Mariage de Figaro.', 2),
    ('2feebccb-06ad-5d82-852d-ec192d40f756'::uuid, 'e9fdaf0b-e8be-54da-8c89-f4c24aefddd5'::uuid, 'Quelle tirade célèbre Bazile prononce-t-il ?', 'mcq', '["La tirade de la calomnie","La tirade des nez","Le monologue du valet","L’éloge du mariage"]'::jsonb, 0, 'Elle décrit la rumeur qui enfle jusqu’au fracas.', 3),
    ('9bfea64e-b56f-5161-87be-29793f0f20c3'::uuid, 'e9fdaf0b-e8be-54da-8c89-f4c24aefddd5'::uuid, 'Comment le comte s’introduit-il chez Bartholo ?', 'mcq', '["Déguisé en soldat ivre, puis en maître de musique remplaçant","Par une échelle de corde","En achetant la maison","En se faisant passer pour un notaire"]'::jsonb, 0, 'Les déguisements successifs organisent l’intrigue.', 4),
    ('adfd00a0-5e04-5cd8-a2d0-f3ede5369e46'::uuid, 'e9fdaf0b-e8be-54da-8c89-f4c24aefddd5'::uuid, 'À quelle trilogie la pièce appartient-elle ?', 'mcq', '["La trilogie de Figaro","La trilogie marseillaise","La trilogie des Rougon","Aucune"]'::jsonb, 0, 'Avec Le Mariage de Figaro et La Mère coupable.', 5),
    ('c5b999bb-2b7b-5630-9cc1-fe703805eb53'::uuid, 'e9fdaf0b-e8be-54da-8c89-f4c24aefddd5'::uuid, 'Figaro est déjà le protagoniste politique de cette pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est encore l’adjuvant brillant du maître : ce sera Le Mariage de Figaro, en 1784.', 6),
    ('23db7781-8f3c-5c7d-afdd-79d99c8234bd'::uuid, '73652ed4-d98b-5641-b5ab-14f04066313c'::uuid, 'Où se déroule le roman ?', 'mcq', '["En Transylvanie, autour d’un château abandonné","En Écosse","Dans les Alpes","En Bohême"]'::jsonb, 0, 'Les villageois de Werst redoutent le lieu.', 1),
    ('12716316-14b5-53af-9138-7985744f7919'::uuid, '73652ed4-d98b-5641-b5ab-14f04066313c'::uuid, 'Qui est La Stilla ?', 'mcq', '["Une cantatrice célèbre, morte sur scène cinq ans plus tôt","La fille du baron","Une paysanne du village","Une servante du château"]'::jsonb, 0, 'Franz de Télek l’avait aimée.', 2),
    ('cdb634e0-5c34-5ffa-914f-e4ef3955fc65'::uuid, '73652ed4-d98b-5641-b5ab-14f04066313c'::uuid, 'Comment s’explique l’apparition de La Stilla ?', 'mcq', '["Un enregistrement phonographique et une projection par miroirs","Un fantôme réel","Une hallucination collective","Une sœur jumelle"]'::jsonb, 0, 'Le fantastique est démonté par la technique.', 3),
    ('92391bc7-f66e-54fa-b612-3fb1a6e846c7'::uuid, '73652ed4-d98b-5641-b5ab-14f04066313c'::uuid, 'Quelle invention le roman préfigure-t-il ?', 'mcq', '["Le cinéma","La télévision par satellite","Le téléphone","La radio"]'::jsonb, 0, 'Quelques années avant les frères Lumière.', 4),
    ('93a73683-1489-53f4-bb11-decd289f1731'::uuid, '73652ed4-d98b-5641-b5ab-14f04066313c'::uuid, 'Que devient Franz après la découverte ?', 'mcq', '["Il sombre dans la folie avant de guérir","Il épouse La Stilla","Il meurt dans l’explosion","Il devient le maître du château"]'::jsonb, 0, 'Le château saute à la fin du roman.', 5),
    ('a09f9342-d5a8-5ded-ae29-5efbe3dc5c01'::uuid, '73652ed4-d98b-5641-b5ab-14f04066313c'::uuid, 'Le roman conclut à l’existence réelle du surnaturel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Verne fait exactement l’inverse : « cette histoire n’est pas fantastique ».', 6),
    ('e1b044f8-7c1e-5919-87f3-316c95e79378'::uuid, '36a91f5c-e1ee-5047-87cb-c52a27f5de39'::uuid, 'Pourquoi Rodrigue tue-t-il le père de Chimène ?', 'mcq', '["Pour laver l’affront fait à son propre père","Par jalousie","Sur ordre du roi","Par accident"]'::jsonb, 0, 'Don Diègue est trop vieux pour se venger lui-même.', 1),
    ('b7259e56-2ca5-5528-a313-fc19ec5579ea'::uuid, '36a91f5c-e1ee-5047-87cb-c52a27f5de39'::uuid, 'Comment appelle-t-on le monologue de délibération de Rodrigue ?', 'mcq', '["Les stances","Le récit de Théramène","La tirade des nez","L’imprécation"]'::jsonb, 0, 'Il y pèse l’honneur contre l’amour.', 2),
    ('69399b8e-1fa5-58b6-8c55-3b9d7136155f'::uuid, '36a91f5c-e1ee-5047-87cb-c52a27f5de39'::uuid, 'Que fait Chimène après la mort de son père ?', 'mcq', '["Elle réclame la mort de Rodrigue tout en l’aimant","Elle pardonne aussitôt","Elle entre au couvent","Elle fuit la cour"]'::jsonb, 0, 'Le devoir et l’amour la déchirent également.', 3),
    ('75943d75-bdf7-56cd-a266-2af4996d746b'::uuid, '36a91f5c-e1ee-5047-87cb-c52a27f5de39'::uuid, 'Comment Rodrigue devient-il « le Cid » ?', 'mcq', '["En repoussant une invasion maure","En gagnant un tournoi","Par une décision du roi","Par héritage"]'::jsonb, 0, 'Ce sont ses ennemis qui lui donnent ce nom.', 4),
    ('a8f2fc31-a579-557a-8b44-43e59f48ac23'::uuid, '36a91f5c-e1ee-5047-87cb-c52a27f5de39'::uuid, 'Que reprochait l’Académie française à la pièce ?', 'mcq', '["D’enfreindre les unités et la bienséance","D’être écrite en prose","De manquer d’action","D’être trop courte"]'::jsonb, 0, 'C’est la querelle du Cid, en 1637.', 5),
    ('191f38de-33d0-5da1-a8f3-93ee95159677'::uuid, '36a91f5c-e1ee-5047-87cb-c52a27f5de39'::uuid, 'La pièce se termine par le mariage immédiat de Rodrigue et Chimène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le roi le diffère d’un an : la fin reste ouverte.', 6),
    ('1db26ee3-603b-5f92-9d12-a30b6b50ab6e'::uuid, 'e83f4906-d3be-52d6-8943-213ac928cad1'::uuid, 'Qui est le colonel Chabert ?', 'mcq', '["Un héros d’Eylau déclaré mort, revenu réclamer son identité","Un notaire ruiné","Un officier de la Restauration","Un aventurier imposteur"]'::jsonb, 0, 'Il s’est extrait d’une fosse commune.', 1),
    ('19fae2f9-214c-5731-b7fb-fd3c0df5c9c2'::uuid, 'e83f4906-d3be-52d6-8943-213ac928cad1'::uuid, 'Pourquoi sa femme refuse-t-elle de le reconnaître ?', 'mcq', '["Elle s’est remariée et a hérité de sa fortune","Elle ne le reconnaît pas physiquement","Elle est menacée","Elle est partie à l’étranger"]'::jsonb, 0, 'Elle est devenue comtesse Ferraud.', 2),
    ('fe93f3c2-39ae-5592-823d-b20aeba43939'::uuid, 'e83f4906-d3be-52d6-8943-213ac928cad1'::uuid, 'Quel personnage aide Chabert ?', 'mcq', '["L’avoué Derville","Le comte Ferraud","Le notaire Roguin","Le juge de paix"]'::jsonb, 0, 'Il est le témoin lucide du récit.', 3),
    ('42b4a821-3c33-508a-8ab1-2b5c24a0f7ae'::uuid, 'e83f4906-d3be-52d6-8943-213ac928cad1'::uuid, 'Que décide finalement Chabert ?', 'mcq', '["Il renonce à sa fortune, à son nom et à son identité","Il gagne son procès","Il tue sa femme","Il part à l’étranger avec Derville"]'::jsonb, 0, 'Le dégoût l’emporte sur l’intérêt.', 4),
    ('ae46ce7c-f82c-50f2-84e9-63f4c5b6a9fd'::uuid, 'e83f4906-d3be-52d6-8943-213ac928cad1'::uuid, 'Où Derville le retrouve-t-il des années plus tard ?', 'mcq', '["À l’hospice de Bicêtre, désigné par un numéro","Sur un champ de bataille","Dans une prison","Dans une ferme de province"]'::jsonb, 0, 'La perte d’identité y est achevée.', 5),
    ('05295eb2-e06f-5122-9d23-142cd780d3e2'::uuid, 'e83f4906-d3be-52d6-8943-213ac928cad1'::uuid, 'Le roman montre la justice comme une protection efficace des innocents.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la montre comme une machine où l’argent et le temps décident.', 6),
    ('49597f2f-8d3e-5887-921a-687c168499ec'::uuid, '3c7a0681-3e3e-5ef2-91ba-a0c0997d478e'::uuid, 'Pourquoi Edmond Dantès est-il emprisonné ?', 'mcq', '["Il est dénoncé par jalousie et par calcul politique","Pour vol","Pour désertion","Par erreur d’identité"]'::jsonb, 0, 'Danglars, Fernand et Villefort y ont chacun leur part.', 1),
    ('5797d908-61a4-5cda-a49f-6abb8cb37453'::uuid, '3c7a0681-3e3e-5ef2-91ba-a0c0997d478e'::uuid, 'Combien de temps reste-t-il au château d’If ?', 'mcq', '["Quatorze ans","Deux ans","Trente ans","Cinq ans"]'::jsonb, 0, 'L’abbé Faria l’y instruit et lui révèle le complot.', 2),
    ('e663dbaf-20c7-53ac-9db3-07e5f0fbc3ee'::uuid, '3c7a0681-3e3e-5ef2-91ba-a0c0997d478e'::uuid, 'Comment Dantès s’évade-t-il ?', 'mcq', '["En prenant la place du mort dans un sac jeté à la mer","En creusant un tunnel jusqu’à la côte","En soudoyant un gardien","Lors d’un transfert"]'::jsonb, 0, 'L’évasion est l’un des morceaux les plus célèbres du roman.', 3),
    ('a6fa5cb3-18d9-581b-9fbb-0dda8794eb16'::uuid, '3c7a0681-3e3e-5ef2-91ba-a0c0997d478e'::uuid, 'Que trouve-t-il sur l’île de Monte-Cristo ?', 'mcq', '["Un trésor légué par l’abbé Faria","Un navire","Des documents compromettants","Une famille amie"]'::jsonb, 0, 'Il en tire son identité de comte.', 4),
    ('0ece5cc1-9d91-564c-837c-660b45b76d82'::uuid, '3c7a0681-3e3e-5ef2-91ba-a0c0997d478e'::uuid, 'Quelle question morale le roman pose-t-il ?', 'mcq', '["Jusqu’où la vengeance est-elle juste ?","Faut-il pardonner à l’État ?","La richesse rend-elle heureux ?","La justice existe-t-elle en mer ?"]'::jsonb, 0, 'La vengeance atteint des innocents, et Dantès s’en trouble.', 5),
    ('5002bd10-1305-5af5-aaf2-ec8712998729'::uuid, '3c7a0681-3e3e-5ef2-91ba-a0c0997d478e'::uuid, 'Dumas a écrit ce roman seul.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’a écrit avec Auguste Maquet, comme la plupart de ses grands romans.', 6),
    ('026b5b67-e38d-5c11-b433-4b1c32693f47'::uuid, '22109d34-63ab-5fdb-ad3d-325c7f3ffbd6'::uuid, 'Que sait-on du narrateur ?', 'mcq', '["Ni son nom, ni son crime","Son nom seulement","Son crime seulement","Tout son passé"]'::jsonb, 0, 'Hugo l’a voulu ainsi pour empêcher le lecteur de se rassurer.', 1),
    ('a816743f-ce80-5710-8f93-1b1681ee8264'::uuid, '22109d34-63ab-5fdb-ad3d-325c7f3ffbd6'::uuid, 'Quelle est la forme du récit ?', 'mcq', '["Un journal à la première personne, en chapitres brefs","Un plaidoyer d’avocat","Un dialogue en prison","Un poème"]'::jsonb, 0, 'Quarante-neuf chapitres, jusqu’aux dernières minutes.', 2),
    ('724e37e0-aa0f-5e02-bcc1-1828cae1d55e'::uuid, '22109d34-63ab-5fdb-ad3d-325c7f3ffbd6'::uuid, 'Quelle scène bouleverse le condamné avant l’exécution ?', 'mcq', '["La visite de sa fille, qui ne le reconnaît plus","La lecture du verdict","La confession au prêtre","La rencontre d’un autre condamné"]'::jsonb, 0, 'Elle ôte au personnage son dernier lien au monde.', 3),
    ('d8a6572d-881a-597a-acde-900c5c8d42b4'::uuid, '22109d34-63ab-5fdb-ad3d-325c7f3ffbd6'::uuid, 'Par quels mots le récit s’achève-t-il ?', 'mcq', '["« QUATRE HEURES »","« Adieu »","« C’est fini »","« Je meurs innocent »"]'::jsonb, 0, 'Le texte s’arrête net, au moment de l’exécution.', 4),
    ('5c9ed12d-fbb7-553a-ab6c-1301b85a5473'::uuid, '22109d34-63ab-5fdb-ad3d-325c7f3ffbd6'::uuid, 'Quel est le but de l’œuvre ?', 'mcq', '["Plaider contre la peine de mort en la faisant éprouver","Raconter un fait divers","Défendre un innocent réel","Décrire les prisons de Paris"]'::jsonb, 0, 'L’argument est expérimental plus que juridique.', 5),
    ('ac6f6aa3-e43d-5f50-9bbc-4dd3dda6ac40'::uuid, '22109d34-63ab-5fdb-ad3d-325c7f3ffbd6'::uuid, 'La peine de mort a été abolie en France peu après la publication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faudra attendre 1981 : Hugo a mené ce combat toute sa vie.', 6),
    ('613d845f-0e9d-5c43-9f0a-856b3e705065'::uuid, '8c29cfe3-c7f8-5aa3-8919-d29ad8999576'::uuid, 'Que découvre Pontagnac en suivant une femme dans la rue ?', 'mcq', '["Qu’elle est la femme de son ami Vatelin","Qu’elle est mariée à un policier","Qu’elle est sa cousine","Qu’elle est une actrice célèbre"]'::jsonb, 0, 'La situation initiale enclenche toute la mécanique.', 1),
    ('6f005456-d71b-5eac-a90d-0479be45e0d7'::uuid, '8c29cfe3-c7f8-5aa3-8919-d29ad8999576'::uuid, 'Quelle promesse Lucienne fait-elle ?', 'mcq', '["Ne céder à Pontagnac que si son mari la trompe","Ne jamais revoir Pontagnac","Quitter Paris","Divorcer immédiatement"]'::jsonb, 0, 'Le vaudeville transforme aussitôt la condition en piège.', 2),
    ('8b458161-a81a-5c5f-95fc-8e16fa4dac16'::uuid, '8c29cfe3-c7f8-5aa3-8919-d29ad8999576'::uuid, 'Où se déroule l’acte central ?', 'mcq', '["À l’hôtel Ultimus","Chez les Vatelin","Au théâtre","Dans un restaurant"]'::jsonb, 0, 'Portes, sonnerie électrique et lit à ressorts y font le reste.', 3),
    ('1ba3b8c1-26a9-5de3-b06a-daea7e1f7fe3'::uuid, '8c29cfe3-c7f8-5aa3-8919-d29ad8999576'::uuid, 'Qui est « le dindon » de la farce ?', 'mcq', '["Pontagnac, découvert par sa propre femme","Vatelin","Maggy","Le commissaire"]'::jsonb, 0, 'Celui qui manœuvre le plus est celui qui perd.', 4),
    ('9cb67cee-46fd-5a52-b0c3-753cda5a0afd'::uuid, '8c29cfe3-c7f8-5aa3-8919-d29ad8999576'::uuid, 'Que dénonce la pièce sous le rire ?', 'mcq', '["Le mariage bourgeois et l’adultère devenu convention","La corruption politique","La misère ouvrière","La justice de classe"]'::jsonb, 0, 'Personne n’y agit vraiment par désir.', 5),
    ('a43067cf-118f-5dda-834a-a270b7538537'::uuid, '8c29cfe3-c7f8-5aa3-8919-d29ad8999576'::uuid, 'La pièce se termine par plusieurs adultères accomplis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Personne n’a réussi à tromper personne : l’ordre revient intact.', 6),
    ('b41ddded-8312-5513-a94a-3b1e849c8632'::uuid, 'b00d8fcd-bcf1-5b51-9abb-6bc07b52e59b'::uuid, 'Qui raconte l’histoire ?', 'mcq', '["François Seurel, le camarade de Meaulnes","Meaulnes lui-même","Yvonne de Galais","Un narrateur omniscient"]'::jsonb, 0, 'Fils d’instituteur, il observe et rapporte.', 1),
    ('cb075207-710f-5344-8e4f-96a6ddf47300'::uuid, 'b00d8fcd-bcf1-5b51-9abb-6bc07b52e59b'::uuid, 'Que découvre Meaulnes pendant sa disparition ?', 'mcq', '["Un domaine mystérieux où se déroule une fête étrange","Une ville abandonnée","Un cirque ambulant","Une famille de bohémiens"]'::jsonb, 0, 'Il y rencontre Yvonne de Galais.', 2),
    ('d1ad9d2e-47e4-5b5d-a96e-b358ecf4a6eb'::uuid, 'b00d8fcd-bcf1-5b51-9abb-6bc07b52e59b'::uuid, 'Quel est le drame du roman ?', 'mcq', '["Meaulnes ne parvient pas à retrouver le chemin du domaine","Yvonne refuse de le revoir","François le trahit","Le domaine n’a jamais existé"]'::jsonb, 0, 'L’absolu entrevu une fois devient introuvable.', 3),
    ('87a92ca7-d653-564a-9998-80b85846b653'::uuid, 'b00d8fcd-bcf1-5b51-9abb-6bc07b52e59b'::uuid, 'Pourquoi Meaulnes repart-il aussitôt après son mariage ?', 'mcq', '["Pour tenir une promesse faite à Frantz de Galais","Parce qu’il n’aime plus Yvonne","Pour chercher du travail","Parce qu’il est appelé à l’armée"]'::jsonb, 0, 'La promesse imprudente détruit son bonheur.', 4),
    ('9a45c7c4-07a1-51dd-8ca7-664372299b82'::uuid, 'b00d8fcd-bcf1-5b51-9abb-6bc07b52e59b'::uuid, 'Quel est le destin de l’auteur ?', 'mcq', '["Il est tué au front en 1914, à vingt-sept ans","Il a écrit dix romans","Il est mort de maladie en 1950","Il a cessé d’écrire après ce livre"]'::jsonb, 0, 'Le Grand Meaulnes est son unique roman.', 5),
    ('a3e33311-849c-5d15-9db5-5025455938e1'::uuid, 'b00d8fcd-bcf1-5b51-9abb-6bc07b52e59b'::uuid, 'Le roman est un pur conte, sans ancrage réaliste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’école, la Sologne et les saisons y sont peintes avec précision.', 6),
    ('ec4987ab-c1fd-56f6-a2ac-6da6f832b856'::uuid, 'e8948a3a-005a-5acf-b458-f53a4adb3494'::uuid, 'Quel moment historique le roman décrit-il ?', 'mcq', '["Le Risorgimento : le débarquement de Garibaldi en Sicile, en 1860","La Première Guerre mondiale","Le fascisme","Les guerres napoléoniennes"]'::jsonb, 0, 'L’unité italienne se fait sous les yeux du prince Salina.', 1),
    ('8aef37b3-58b8-5437-86af-1b9c886575e2'::uuid, 'e8948a3a-005a-5acf-b458-f53a4adb3494'::uuid, 'Quelle est la formule la plus célèbre du roman ?', 'mcq', '["« Il faut que tout change pour que rien ne change »","« Rien ne se perd, rien ne se crée »","« Après moi, le déluge »","« La fin justifie les moyens »"]'::jsonb, 0, 'Elle est prononcée par Tancredi.', 2),
    ('438f6269-7082-56d4-940b-f9e5dc48af3c'::uuid, 'e8948a3a-005a-5acf-b458-f53a4adb3494'::uuid, 'Qui épouse Tancredi ?', 'mcq', '["Angelica, fille du maire parvenu","Concetta, la fille du prince","Une aristocrate napolitaine","Personne"]'::jsonb, 0, 'La fortune neuve remplace la noblesse ruinée.', 3),
    ('e99a4f66-9665-56a8-b576-c3fac7848852'::uuid, 'e8948a3a-005a-5acf-b458-f53a4adb3494'::uuid, 'Que refuse le prince Salina ?', 'mcq', '["Un siège de sénateur du nouveau royaume","Le mariage de Tancredi","De quitter la Sicile","De recevoir Sedàra"]'::jsonb, 0, 'Il explique que les Siciliens ne veulent pas changer.', 4),
    ('6ce70123-a6cc-5040-97b8-02c3db09d661'::uuid, 'e8948a3a-005a-5acf-b458-f53a4adb3494'::uuid, 'Quand le roman a-t-il été publié ?', 'mcq', '["En 1958, après la mort de son auteur","En 1930","En 1945","En 1963"]'::jsonb, 0, 'Il avait été refusé du vivant de Lampedusa.', 5),
    ('cea25a8d-3bd3-52ad-916b-b4615777e89e'::uuid, 'e8948a3a-005a-5acf-b458-f53a4adb3494'::uuid, 'Le roman a été adapté au cinéma par Visconti.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'En 1963, avec Burt Lancaster, Alain Delon et Claudia Cardinale.', 6),
    ('b0b82e2a-d795-5ae4-a12d-984df4ee81e5'::uuid, '13fac390-9149-5746-818a-7a2db7828d17'::uuid, 'Quelle est la forme du récit ?', 'mcq', '["Un journal intime","Une lettre","Un récit à la troisième personne","Un dialogue avec un médecin"]'::jsonb, 0, 'Elle rend sensible la contamination progressive.', 1),
    ('7d855b00-e900-51b3-87a9-517efafa425c'::uuid, '13fac390-9149-5746-818a-7a2db7828d17'::uuid, 'Quels signes inquiètent le narrateur ?', 'mcq', '["Sa carafe se vide, une rose se coupe seule, une page se tourne","Des bruits dans le grenier","Des lettres anonymes","Des apparitions lumineuses"]'::jsonb, 0, 'Les faits sont minuscules et invérifiables.', 2),
    ('9fc65398-e7e8-5804-908c-3b7449576c37'::uuid, '13fac390-9149-5746-818a-7a2db7828d17'::uuid, 'Comment nomme-t-il l’être invisible ?', 'mcq', '["Le Horla","Le Double","L’Ombre","Le Veilleur"]'::jsonb, 0, 'Le nom lui-même est une invention du narrateur.', 3),
    ('09cd4d10-59d3-5d3e-9f75-cbf82e18060d'::uuid, '13fac390-9149-5746-818a-7a2db7828d17'::uuid, 'Que fait-il pour s’en débarrasser ?', 'mcq', '["Il met le feu à sa maison, tuant ses domestiques","Il déménage","Il consulte un exorciste","Il fuit au Brésil"]'::jsonb, 0, 'Puis il comprend que l’être a survécu.', 4),
    ('43271757-4b9e-5052-bbb7-270e06626aa1'::uuid, '13fac390-9149-5746-818a-7a2db7828d17'::uuid, 'Qu’est-ce qui définit le fantastique dans ce texte ?', 'mcq', '["L’hésitation entre folie et surnaturel","La présence certaine d’un monstre","L’explication scientifique finale","Le décor médiéval"]'::jsonb, 0, 'Todorov en a fait la définition même du genre.', 5),
    ('6ac4141f-1fa6-5f6b-a959-b732c212943e'::uuid, '13fac390-9149-5746-818a-7a2db7828d17'::uuid, 'Le récit tranche clairement en faveur du surnaturel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Rien ne permet de décider : c’est ce qui fait sa force.', 6),
    ('a078bbe8-16e0-528c-9145-10f6cd966acb'::uuid, '24dfd4b4-6c3e-5a33-b9ad-571dd6929d5b'::uuid, 'Quelle épidémie traverse le roman ?', 'mcq', '["Le choléra de 1832","La peste noire","La grippe espagnole","La variole"]'::jsonb, 0, 'Le roman se déroule en Provence.', 1),
    ('51c4f8fe-a483-5371-b821-285dfb553ab3'::uuid, '24dfd4b4-6c3e-5a33-b9ad-571dd6929d5b'::uuid, 'Qui est Angelo Pardi ?', 'mcq', '["Un jeune colonel de hussards piémontais, carbonaro en fuite","Un médecin français","Un prêtre italien","Un marchand de Manosque"]'::jsonb, 0, 'Il est poursuivi comme empoisonneur de fontaines.', 2),
    ('e9995f20-6069-5dfa-ab10-fe4ff8308df4'::uuid, '24dfd4b4-6c3e-5a33-b9ad-571dd6929d5b'::uuid, 'Pourquoi se réfugie-t-il sur les toits ?', 'mcq', '["Pour échapper à la foule qui l’accuse","Pour observer les étoiles","Pour soigner les malades","Pour attendre Pauline"]'::jsonb, 0, 'D’où le titre du roman.', 3),
    ('8bebaaf8-cae2-5d70-b16b-54262d6c31e4'::uuid, '24dfd4b4-6c3e-5a33-b9ad-571dd6929d5b'::uuid, 'Comment sauve-t-il Pauline ?', 'mcq', '["En la frictionnant toute une nuit","En lui donnant un remède","En appelant un médecin","En la conduisant à l’hôpital"]'::jsonb, 0, 'La scène est l’un des sommets du livre.', 4),
    ('7c160032-5733-59cf-81ae-22ca2c9277cb'::uuid, '24dfd4b4-6c3e-5a33-b9ad-571dd6929d5b'::uuid, 'Quelle qualité définit le héros ?', 'mcq', '["Une générosité sans calcul","La ruse","L’ambition","La cruauté froide"]'::jsonb, 0, 'Angelo agit toujours bien, ce qui en fait un personnage rare.', 5),
    ('5e2e2fe7-c9c2-51c0-906f-b964d371f96a'::uuid, '24dfd4b4-6c3e-5a33-b9ad-571dd6929d5b'::uuid, 'La relation entre Angelo et Pauline devient une liaison amoureuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La retenue est totale : il la ramène chez elle et repart.', 6),
    ('dc064084-9c8f-5e0a-aab8-4c233f1b5874'::uuid, '27a80090-5582-5a11-a3d2-e165844db136'::uuid, 'Pourquoi Silvia échange-t-elle son rôle avec Lisette ?', 'mcq', '["Pour observer librement le prétendant qu’on lui destine","Pour fuir son père","Pour se moquer de Dorante","Pour aider Lisette à se marier"]'::jsonb, 0, 'Dorante a exactement la même idée de son côté.', 1),
    ('dbb9c8fb-7dad-5500-9420-a19d716d73a5'::uuid, '27a80090-5582-5a11-a3d2-e165844db136'::uuid, 'Sous quel nom Dorante se présente-t-il ?', 'mcq', '["Bourguignon","Arlequin","Mario","Frontin"]'::jsonb, 0, 'Son valet Arlequin se fait passer pour lui.', 2),
    ('dfd34056-5d4d-583d-9367-d865976bc76b'::uuid, '27a80090-5582-5a11-a3d2-e165844db136'::uuid, 'Qui connaît les deux stratagèmes ?', 'mcq', '["Orgon et Mario","Personne","Lisette seule","Arlequin seul"]'::jsonb, 0, 'Ils laissent faire, et observent avec amusement.', 3),
    ('251228d2-5cdc-5f85-8402-58f0ba5eb453'::uuid, '27a80090-5582-5a11-a3d2-e165844db136'::uuid, 'Quelle épreuve Silvia impose-t-elle à Dorante ?', 'mcq', '["Qu’il la demande en mariage en la croyant servante","Qu’il renonce à sa fortune","Qu’il se batte en duel","Qu’il quitte la maison"]'::jsonb, 0, 'Elle prolonge le jeu après l’aveu de Dorante.', 4),
    ('14f3f63d-5269-51f9-80ce-a4c6d0163a9d'::uuid, '27a80090-5582-5a11-a3d2-e165844db136'::uuid, 'Que se passe-t-il pour Arlequin et Lisette ?', 'mcq', '["Ils se découvrent domestiques tous les deux et s’en accommodent","Ils se séparent","Ils épousent leurs maîtres","Ils quittent la maison"]'::jsonb, 0, 'L’ordre social n’est finalement pas renversé.', 5),
    ('85e43df0-3e61-5472-8413-cb6821e6c333'::uuid, '27a80090-5582-5a11-a3d2-e165844db136'::uuid, 'Le déguisement sert d’épreuve pour l’amour dans cette pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Peut-on aimer par-delà la condition sociale ? La réponse est nuancée.', 6),
    ('1474d7ee-da52-5ef9-8747-09df445bae88'::uuid, 'd332f046-00f0-5e54-bd44-d6d5805b490b'::uuid, 'Où se déroule l’essentiel du roman ?', 'mcq', '["En Touraine, à Clochegourde, dans la vallée de l’Indre","À Paris","En Bretagne","En Angleterre"]'::jsonb, 0, 'La vallée y est décrite comme un corps.', 1),
    ('6482ff83-2905-506b-adbb-5b1b529c41d2'::uuid, 'd332f046-00f0-5e54-bd44-d6d5805b490b'::uuid, 'Quelle est la nature de la relation entre Félix et Henriette ?', 'mcq', '["Un amour intense mais jamais consommé","Une liaison secrète","Un mariage arrangé","Une amitié sans trouble"]'::jsonb, 0, 'Henriette impose la vertu tout en vivant de cette passion.', 2),
    ('ffd19670-9a97-5ed8-8e81-cb9acc2602eb'::uuid, 'd332f046-00f0-5e54-bd44-d6d5805b490b'::uuid, 'Qui est lady Dudley ?', 'mcq', '["Une Anglaise sensuelle dont Félix devient l’amant à Paris","La sœur d’Henriette","La mère de Félix","Une amie de Clochegourde"]'::jsonb, 0, 'Henriette l’apprend et se laisse mourir.', 3),
    ('468f915d-4fc6-55b7-9325-a24ddd7741cc'::uuid, 'd332f046-00f0-5e54-bd44-d6d5805b490b'::uuid, 'Comment meurt Henriette ?', 'mcq', '["De faim et de chagrin","D’une maladie contagieuse","En couches","Assassinée"]'::jsonb, 0, 'Elle laisse une lettre où elle avoue tout ce qu’elle avait réprimé.', 4),
    ('a4d51c79-6184-50ae-a7eb-cdc2ac3f4d8c'::uuid, 'd332f046-00f0-5e54-bd44-d6d5805b490b'::uuid, 'À quel livre le roman répond-il ?', 'mcq', '["Volupté de Sainte-Beuve","Adolphe de Constant","René de Chateaubriand","Les Confessions de Rousseau"]'::jsonb, 0, 'Balzac voulait montrer qu’il pouvait traiter ce sujet mieux que lui.', 5),
    ('5fbbb556-5546-59a1-b982-92d3c7e8c10c'::uuid, 'd332f046-00f0-5e54-bd44-d6d5805b490b'::uuid, 'Le roman présente le renoncement comme une réussite morale sereine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le montre comme une souffrance et une forme de destruction.', 6),
    ('abc0a446-2d5b-5c4e-88b2-d774d09eb0d7'::uuid, '463fcda7-c46a-5797-ba48-6c3ca08f728b'::uuid, 'Que veut Argan pour sa fille ?', 'mcq', '["Un mari médecin, Thomas Diafoirus","Un mariage riche","Un couvent","Un mariage avec Cléante"]'::jsonb, 0, 'Il veut un médecin dans la famille pour lui seul.', 1),
    ('d254f8d0-4da4-5aa8-8b22-683159500712'::uuid, '463fcda7-c46a-5797-ba48-6c3ca08f728b'::uuid, 'Quel stratagème démasque Béline ?', 'mcq', '["Argan fait semblant d’être mort","Toinette lit ses lettres","Béralde la piège au notaire","Angélique la dénonce"]'::jsonb, 0, 'Elle se réjouit devant le corps, tandis qu’Angélique pleure.', 2),
    ('890492a0-7be8-53a7-8882-8a1a5a95b595'::uuid, '463fcda7-c46a-5797-ba48-6c3ca08f728b'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Par une cérémonie burlesque où Argan est reçu médecin","Par la guérison d’Argan","Par la mort d’Argan","Par le départ de Toinette"]'::jsonb, 0, 'En faux latin, avec chants et danses.', 3),
    ('3c25b0fd-0f3c-5034-83ec-bdaa1d55ec1f'::uuid, '463fcda7-c46a-5797-ba48-6c3ca08f728b'::uuid, 'Qu’est-il arrivé à Molière lors des représentations ?', 'mcq', '["Pris de malaise à la quatrième, il meurt le soir même","Il a été arrêté","Il a refusé de jouer","Il a été blessé sur scène"]'::jsonb, 0, 'Il jouait le rôle d’Argan.', 4),
    ('0db0a4ed-cdfb-5676-9539-2944cb961442'::uuid, '463fcda7-c46a-5797-ba48-6c3ca08f728b'::uuid, 'Que vise la satire de la pièce ?', 'mcq', '["La médecine comme pouvoir : jargon, autorité, latin","Les malades imaginaires seulement","Le mariage arrangé uniquement","La religion"]'::jsonb, 0, 'Béralde formule la critique : la nature guérit, les médecins font des cérémonies.', 5),
    ('e7dc6813-925d-52ad-aa3d-401c661ed461'::uuid, '463fcda7-c46a-5797-ba48-6c3ca08f728b'::uuid, 'Le théâtre est présenté comme un moyen d’atteindre la vérité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne guérit Argan qu’en jouant : déguisement, fausse mort, cérémonie.', 6),
    ('a5593cca-5db4-5e1f-b0ae-bfb5e9c4c67b'::uuid, '6a74bc96-9e40-5702-b911-5210c61278c7'::uuid, 'Que veut le comte Almaviva ?', 'mcq', '["Faire valoir sur Suzanne un droit qu’il avait aboli","Marier Figaro à Marceline","Chasser Chérubin","Vendre le château"]'::jsonb, 0, 'Toute la journée se passe à déjouer ses manœuvres.', 1),
    ('563c587c-a97d-5306-adad-12adae2905a4'::uuid, '6a74bc96-9e40-5702-b911-5210c61278c7'::uuid, 'Que révèle le procès burlesque ?', 'mcq', '["Marceline est la mère de Figaro","Suzanne est noble","Le comte est ruiné","Chérubin est le fils du comte"]'::jsonb, 0, 'La créancière devient mère : coup de théâtre classique.', 2),
    ('e2a3e422-bf7d-513a-995f-42dbd9e828e9'::uuid, '6a74bc96-9e40-5702-b911-5210c61278c7'::uuid, 'Que contient le monologue de l’acte V ?', 'mcq', '["Le bilan d’une vie et la dénonciation du privilège de naissance","Une déclaration d’amour","Un plan d’évasion","Un éloge du comte"]'::jsonb, 0, 'C’est le plus long monologue du théâtre français classique.', 3),
    ('6d395a3f-8ddb-561a-adfc-6df92051c134'::uuid, '6a74bc96-9e40-5702-b911-5210c61278c7'::uuid, 'Qui organise le piège final du jardin ?', 'mcq', '["Suzanne et la comtesse","Figaro seul","Chérubin","Marceline"]'::jsonb, 0, 'Le renversement est aussi féminin.', 4),
    ('515fb9e7-8259-559a-b5c1-4c8baa7a1d24'::uuid, '6a74bc96-9e40-5702-b911-5210c61278c7'::uuid, 'Pourquoi la pièce a-t-elle été interdite trois ans ?', 'mcq', '["Pour sa charge contre les privilèges et l’ordre social","Pour obscénité seulement","Parce que Beaumarchais était en prison","Faute de théâtre disponible"]'::jsonb, 0, 'Louis XVI en avait mesuré la portée.', 5),
    ('0baa2a52-d310-5ef0-8f7a-25d4937c37e6'::uuid, '6a74bc96-9e40-5702-b911-5210c61278c7'::uuid, 'Figaro cesse d’être valet à la fin de la pièce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se marie mais reste au service du comte : l’égalité est gagnée dans le rire.', 6),
    ('02fdb691-f572-5b56-a543-18041c76565d'::uuid, '7241a0b0-4bca-5dfd-9af3-b12932383e0e'::uuid, 'Quel genre de pièce est Le Médecin volant ?', 'mcq', '["Une farce en un acte","Une comédie de mœurs","Une tragi-comédie","Une comédie-ballet"]'::jsonb, 0, 'C’est l’une des toutes premières pièces de Molière.', 1),
    ('2ee8fce9-9ae0-5fa8-a7db-8e510bbc9294'::uuid, '7241a0b0-4bca-5dfd-9af3-b12932383e0e'::uuid, 'Pourquoi Sganarelle se déguise-t-il en médecin ?', 'mcq', '["Pour couvrir la fausse maladie de Lucile","Pour soigner Gorgibus","Pour gagner de l’argent","Pour se venger de Valère"]'::jsonb, 0, 'Il invente un jargon savant avec un aplomb délirant.', 2),
    ('264c3d9d-ded5-5ce9-b4e7-0830992070e2'::uuid, '7241a0b0-4bca-5dfd-9af3-b12932383e0e'::uuid, 'D’où vient le titre de la pièce ?', 'mcq', '["Sganarelle doit passer par la fenêtre pour jouer deux rôles à la fois","Le médecin voyage en carrosse","Un remède fait voler le malade","Le médecin s’enfuit à cheval"]'::jsonb, 0, 'Le comique est d’abord physique.', 3),
    ('f6e53762-40da-5230-bad7-03ea2c71bbe1'::uuid, '7241a0b0-4bca-5dfd-9af3-b12932383e0e'::uuid, 'Quelle tradition théâtrale inspire cette farce ?', 'mcq', '["La commedia dell’arte italienne","La tragédie grecque","Le drame liturgique médiéval","Le théâtre espagnol"]'::jsonb, 0, 'Molière a longtemps partagé la salle avec les Italiens.', 4),
    ('270c4ea7-b1fd-5d58-b43a-f6ffd408201f'::uuid, '7241a0b0-4bca-5dfd-9af3-b12932383e0e'::uuid, 'Quelle pièce ultérieure reprend ce canevas ?', 'mcq', '["Le Médecin malgré lui","Le Malade imaginaire","L’Amour médecin","Monsieur de Pourceaugnac"]'::jsonb, 0, 'En 1666, en trois actes et bien plus riche.', 5),
    ('46cf0b03-2770-508c-8823-39bf0ddae933'::uuid, '7241a0b0-4bca-5dfd-9af3-b12932383e0e'::uuid, 'Cette farce annonce déjà des types que Molière reprendra.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le valet metteur en scène, le père obstiné et le médecin charlatan y sont déjà.', 6),
    ('d48ce1a0-3145-5d2a-b4a3-2c9802e1d6bf'::uuid, '406e4bcc-6465-581b-b7f1-a97550eca78a'::uuid, 'Comment naissent les humains dans ce monde ?', 'mcq', '["Produits en flacons et conditionnés en cinq castes","Par familles traditionnelles","Par clonage volontaire d’adultes","Ils sont importés des réserves"]'::jsonb, 0, 'Des Alphas aux Epsilons, chacun est programmé pour aimer sa condition.', 1),
    ('1cedcce9-925b-5f3e-ac38-47b3a1b0eb16'::uuid, '406e4bcc-6465-581b-b7f1-a97550eca78a'::uuid, 'Qu’est-ce que le soma ?', 'mcq', '["Une drogue du bonheur sans effets secondaires","Un aliment de synthèse","Un examen d’aptitude","Un moyen de transport"]'::jsonb, 0, 'Il éteint toute insatisfaction, donc toute révolte.', 2),
    ('d520e65f-8c4f-5f4b-a7b4-45252156b31a'::uuid, '406e4bcc-6465-581b-b7f1-a97550eca78a'::uuid, 'Qui est John le Sauvage ?', 'mcq', '["Un homme élevé hors du système, nourri de Shakespeare","Un Alpha rebelle","Un administrateur mondial","Un embryon raté"]'::jsonb, 0, 'Il réclame le droit d’être malheureux.', 3),
    ('a02579a5-6c88-5bcb-a967-c38f23259063'::uuid, '406e4bcc-6465-581b-b7f1-a97550eca78a'::uuid, 'En quoi ce roman diffère-t-il de 1984 ?', 'mcq', '["La dictature s’y impose par le plaisir, non par la terreur","Il se déroule au XIXe siècle","Il n’y a pas d’État","La technologie y est absente"]'::jsonb, 0, 'Les deux romans sont complémentaires.', 4),
    ('046231f2-9bd1-501d-855f-f5296f8f2bd0'::uuid, '406e4bcc-6465-581b-b7f1-a97550eca78a'::uuid, 'D’où vient le titre du roman ?', 'mcq', '["D’une réplique de La Tempête de Shakespeare","D’un poème de Milton","De la Bible","D’un slogan publicitaire"]'::jsonb, 0, 'La citation est ironique.', 5),
    ('8cdbe447-9394-5877-bc5d-6d796edcb175'::uuid, '406e4bcc-6465-581b-b7f1-a97550eca78a'::uuid, 'Le roman se termine par la révolte victorieuse de John.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Devenu curiosité médiatique, il se pend.', 6),
    ('8a19d521-d1d9-52d4-a882-f082f5ae2c8b'::uuid, 'f72cd1cb-dcb3-5f42-920a-f56c0547b099'::uuid, 'D’où vient Dorante au début de la pièce ?', 'mcq', '["De Poitiers","De Lyon","De Bordeaux","De Madrid"]'::jsonb, 0, 'Il abandonne le droit pour se faire homme du monde à Paris.', 1),
    ('5bccc923-7655-5c41-bb66-406caab842e1'::uuid, 'f72cd1cb-dcb3-5f42-920a-f56c0547b099'::uuid, 'Quel premier mensonge invente-t-il ?', 'mcq', '["Un passé de guerrier revenu d’Allemagne","Une fortune héritée","Un titre de noblesse","Une carrière de poète"]'::jsonb, 0, 'Tous les autres mensonges en découlent.', 2),
    ('7620699a-707b-5b43-aaa1-d430fa6c13ee'::uuid, 'f72cd1cb-dcb3-5f42-920a-f56c0547b099'::uuid, 'Sur quel quiproquo repose l’intrigue ?', 'mcq', '["Une confusion entre les noms de Clarice et de Lucrèce","Un échange de lettres","Un déguisement","Une fausse mort"]'::jsonb, 0, 'Elle manque de le faire tuer en duel.', 3),
    ('a864c08f-1ea7-5672-97cb-1227164ec7ca'::uuid, 'f72cd1cb-dcb3-5f42-920a-f56c0547b099'::uuid, 'Quel est le rôle de Cliton ?', 'mcq', '["Valet lucide, il commente les mensonges de son maître","Rival amoureux","Père de Clarice","Ami d’enfance de Lucrèce"]'::jsonb, 0, 'Il sert de relais au spectateur.', 4),
    ('f8af1237-261f-5773-88ea-9dee3ea41cb8'::uuid, 'f72cd1cb-dcb3-5f42-920a-f56c0547b099'::uuid, 'De quelle pièce Corneille s’inspire-t-il ?', 'mcq', '["La Verdad sospechosa d’Alarcón","La Vie est un songe de Calderón","La Célestine","Le Trompeur de Séville"]'::jsonb, 0, 'Il l’adapte librement au cadre parisien.', 5),
    ('73fbf650-849f-5279-9809-e86821b9326a'::uuid, 'f72cd1cb-dcb3-5f42-920a-f56c0547b099'::uuid, 'Le menteur est puni au dénouement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il épouse la femme qu’il aime : ni puni ni corrigé.', 6),
    ('539a4525-b474-50d9-8e79-fac9d20eca42'::uuid, '65ac7813-9c98-553e-b0d0-4be5de3028db'::uuid, 'Que refuse Alceste ?', 'mcq', '["Les flatteries et les compromis de la vie mondaine","Le mariage","La justice royale","La poésie"]'::jsonb, 0, 'Il exige la sincérité absolue en toute circonstance.', 1),
    ('354be74a-ff42-54be-9699-9c2b77b0e10c'::uuid, '65ac7813-9c98-553e-b0d0-4be5de3028db'::uuid, 'Qui incarne la mesure face à Alceste ?', 'mcq', '["Philinte","Oronte","Acaste","Du Bois"]'::jsonb, 0, 'Sa sagesse ressemble parfois à de la complaisance.', 2),
    ('0ff85554-29b6-5392-9112-5be8e0795a4f'::uuid, '65ac7813-9c98-553e-b0d0-4be5de3028db'::uuid, 'Pourquoi Alceste se retrouve-t-il en procès ?', 'mcq', '["Il a critiqué durement le sonnet d’Oronte","Il a insulté le roi","Il a refusé de payer une dette","Il a frappé un rival"]'::jsonb, 0, 'La sincérité a un coût social immédiat.', 3),
    ('f0b67029-6847-575b-b660-68e8ffa091a5'::uuid, '65ac7813-9c98-553e-b0d0-4be5de3028db'::uuid, 'Qui est Célimène ?', 'mcq', '["Une jeune veuve brillante et coquette qui tient salon","La sœur d’Alceste","Une prude retirée","Une servante"]'::jsonb, 0, 'Elle croque tous les absents en portraits féroces.', 4),
    ('aa8f9baa-191d-5773-85c4-9fc3ca166665'::uuid, '65ac7813-9c98-553e-b0d0-4be5de3028db'::uuid, 'Que propose Alceste à Célimène à la fin ?', 'mcq', '["Le suivre au désert, loin du monde","L’épouser à la cour","Renoncer à son procès","Fuir à l’étranger avec Philinte"]'::jsonb, 0, 'Elle refuse : elle a vingt ans. Alceste part seul.', 5),
    ('5cbad75b-d075-5f5f-b545-45b9bdd6bfcc'::uuid, '65ac7813-9c98-553e-b0d0-4be5de3028db'::uuid, 'Molière donne clairement raison à Alceste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a raison sur le fond et tort dans la vie : la pièce ne tranche pas.', 6),
    ('c6bd8a82-c53b-5369-bcca-1867ff562128'::uuid, 'f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Quelle est la forme de l’œuvre ?', 'mcq', '["Un dialogue entre MOI et LUI","Un roman à la première personne","Un traité de musique","Un recueil de lettres"]'::jsonb, 0, 'La rencontre a lieu au café de la Régence.', 1),
    ('ea3d1666-dc6f-54c5-bf10-3d817b496f51'::uuid, 'f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Qui est « LUI » ?', 'mcq', '["Jean-François Rameau, neveu du compositeur, parasite génial","Diderot lui-même","Un noble anonyme","Un valet de comédie"]'::jsonb, 0, 'Musicien raté et pique-assiette, il mime et joue tous les rôles.', 2),
    ('d133430a-656a-56ab-98f3-4a1f7f04e51f'::uuid, 'f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Que désigne la « pantomime des gueux » ?', 'mcq', '["Les postures qu’il faut prendre pour survivre auprès des puissants","Une danse populaire","Un opéra italien","Un jeu d’enfants"]'::jsonb, 0, '« Il n’y a qu’un homme qui marche, c’est le souverain. »', 3),
    ('c23d5a1e-f663-59f0-98da-f9e8c6039a5c'::uuid, 'f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Comment le texte a-t-il été publié ?', 'mcq', '["D’abord en allemand, traduit par Goethe, en 1805","Du vivant de Diderot, en 1762","En feuilleton au XIXe siècle","Jamais publié intégralement"]'::jsonb, 0, 'Le manuscrit français ne sera retrouvé que bien plus tard.', 4),
    ('875880f1-002b-5228-9ed7-8b65f68c5400'::uuid, 'f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Quels penseurs ont commenté ce texte ?', 'mcq', '["Hegel et Freud","Kant et Descartes","Voltaire et Rousseau seulement","Marx et Comte"]'::jsonb, 0, 'Ils y voient un texte majeur sur la conscience divisée.', 5),
    ('1ba73f3d-06d2-54d0-84a5-1a33dc5ba970'::uuid, 'f335f619-b032-5e88-ac39-f2a40b933b15'::uuid, 'Le philosophe réfute et fait taire le neveu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le contredit, s’indigne — et l’écoute jusqu’au bout, fasciné.', 6),
    ('c16c856d-dc49-5432-a660-7cf894840669'::uuid, '8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Combien de textes le recueil comporte-t-il ?', 'mcq', '["Trente-deux","Douze","Cent","Sept"]'::jsonb, 0, 'Tous en prose, la plupart très brefs.', 1),
    ('8e603011-211d-5f24-b29e-3a25cf78a1ae'::uuid, '8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Quels objets Ponge décrit-il ?', 'mcq', '["Des objets banals : le cageot, l’huître, le pain, la bougie","Des monuments célèbres","Des paysages de montagne","Des animaux exotiques"]'::jsonb, 0, 'Le minuscule est un choix poétique.', 2),
    ('b11c12fc-095c-509b-9f44-a78482fb8819'::uuid, '8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Quel texte fait office de manifeste ?', 'mcq', '["Le Galet","La Pluie","L’Orange","La Cigarette"]'::jsonb, 0, 'Plus long, il expose la démarche.', 3),
    ('990f72e9-a09e-5f84-8f54-06f5b4ba51c5'::uuid, '8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Comment Ponge nomme-t-il son objectif d’écriture ?', 'mcq', '["La définition-description-objet littéraire","Le poème en prose lyrique","L’écriture automatique","Le vers libre descriptif"]'::jsonb, 0, 'Le poème est un objet fabriqué, non un épanchement.', 4),
    ('cc74285f-f06f-5349-bbe3-b9f64ecb3557'::uuid, '8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Quel outil accompagne son travail ?', 'mcq', '["Le dictionnaire et l’étymologie","Le carnet de voyage","La photographie","La musique"]'::jsonb, 0, 'Les doubles sens et les sonorités sont des matériaux.', 5),
    ('66f03d77-4776-50a1-a96e-ab2e5b03572e'::uuid, '8f479882-65d0-5c6c-b754-d69b9e3c39ac'::uuid, 'Ponge refuse le lyrisme par sécheresse de cœur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le refuse par exigence : rendre justice à ce qui n’a pas de voix.', 6),
    ('10c238bf-578a-574d-98c5-f3a328fc4a1a'::uuid, 'ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Qui est Jacob ?', 'mcq', '["Un fils de fermier monté à Paris, beau et débrouillard","Un noble ruiné","Un marchand vénitien","Un valet de comédie"]'::jsonb, 0, 'Il vend d’abord du vin pour son maître.', 1),
    ('5515c18d-b4b7-5c91-a419-8bed8d1b5f10'::uuid, 'ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Comment Jacob s’élève-t-il socialement ?', 'mcq', '["Par la séduction et des mariages ou protections féminines","Par le commerce","Par les armes","Par l’étude"]'::jsonb, 0, 'Chaque femme rencontrée le rapproche du monde qu’il vise.', 2),
    ('c9fb04df-abd8-562b-a152-93b77920998c'::uuid, 'ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Quel nom prend-il en s’élevant ?', 'mcq', '["Monsieur de La Vallée","Monsieur de Valville","Monsieur Dorante","Monsieur de Climal"]'::jsonb, 0, 'Le changement de nom accompagne le changement de condition.', 3),
    ('ac1bb8fe-be62-5f48-9ca7-69469f5fe308'::uuid, 'ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Quelle est la particularité du récit ?', 'mcq', '["Un narrateur âgé juge avec ironie le jeune homme qu’il fut","Un narrateur omniscient","Une succession de lettres","Un dialogue continu"]'::jsonb, 0, 'C’est un roman-mémoires, resté inachevé.', 4),
    ('ef69f4a1-6bf3-51ba-aae7-b9f17a96f6ed'::uuid, 'ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Quel roman de Marivaux forme le pendant féminin ?', 'mcq', '["La Vie de Marianne","Les Fausses Confidences","L’Île des esclaves","La Double Inconstance"]'::jsonb, 0, 'Même époque, même ambition sociale, autre point de vue.', 5),
    ('cc062d39-788c-5c1a-b299-f6f0447080bf'::uuid, 'ec1dfc6f-3269-53c3-a881-c6f7630ca05c'::uuid, 'Le roman se termine par la chute du héros.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est inachevé, et la comédie sociale y reste souriante.', 6),
    ('40aa2b8f-d808-51b0-b926-a141b199cc0f'::uuid, '6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'Où se déroule une grande partie du roman ?', 'mcq', '["À la pension Vauquer","Au Palais-Royal","Dans un hôtel du faubourg Saint-Germain","À la Sorbonne"]'::jsonb, 0, 'La pension réunit tous les milieux sociaux du roman.', 1),
    ('6918c6a4-e629-53af-b701-4cea3c4f5d38'::uuid, '6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'Qui est le père Goriot ?', 'mcq', '["Un ancien vermicellier ruiné par ses deux filles","Un usurier","Un ancien officier","Le propriétaire de la pension"]'::jsonb, 0, 'Anastasie et Delphine ne viennent que pour de l’argent.', 2),
    ('0aebec9f-7774-580a-80c5-e7225015a23e'::uuid, '6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'Quel pacte Vautrin propose-t-il à Rastignac ?', 'mcq', '["Épouser une héritière dont il ferait tuer le frère","Voler la pension Vauquer","Le faire entrer dans la police","Financer ses études"]'::jsonb, 0, 'Vautrin est un forçat évadé sous un faux nom.', 3),
    ('4700de5f-ed8b-5ab8-bcd6-a5aed13ab15d'::uuid, '6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'Comment meurt le père Goriot ?', 'mcq', '["Seul et ruiné, sans qu’aucune de ses filles vienne","Assassiné par Vautrin","Riche et entouré","Dans un accident"]'::jsonb, 0, 'Rastignac l’enterre presque seul.', 4),
    ('5dcabd4f-1e77-5718-9119-ff36f0200c73'::uuid, '6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'Quelle phrase clôt le roman ?', 'mcq', '["« À nous deux maintenant ! »","« Adieu, Paris »","« Tout est perdu »","« Je reviendrai »"]'::jsonb, 0, 'Rastignac lance son défi du haut du Père-Lachaise.', 5),
    ('f935f3a7-b595-503b-8236-38ff5e5db341'::uuid, '6d0df5e5-e9ae-5284-b1a7-8131a5014511'::uuid, 'C’est dans ce roman que Balzac invente le retour des personnages.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Rastignac, Vautrin et Nucingen reparaîtront dans toute La Comédie humaine.', 6),
    ('48eb760c-6e62-57c8-b2d3-5dbf7f75e06d'::uuid, 'eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'Quelle est la forme de ce texte ?', 'mcq', '["Une saynète très brève","Une comédie en cinq actes","Un roman court","Un monologue"]'::jsonb, 0, 'Courteline est le maître de la forme brève comique.', 1),
    ('0e5ecfe6-4a66-50b4-86ce-2e120378c34a'::uuid, 'eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'Sur quoi repose le comique de la pièce ?', 'mcq', '["Un quiproquo médical résolu par une explication dérisoire","Un déguisement","Un jeu de mots répété","Une méprise sur les noms"]'::jsonb, 0, 'L’écart entre le sérieux du ton et la petitesse de la chose.', 2),
    ('9d11de39-58fd-5b55-9259-20952659e2fa'::uuid, 'eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'Quels milieux Courteline peint-il habituellement ?', 'mcq', '["Employés, militaires, ménages et tribunaux","La haute aristocratie","Les milieux artistiques","Le monde paysan"]'::jsonb, 0, 'Messieurs les ronds-de-cuir en est le meilleur exemple.', 3),
    ('ba6ef708-3b44-59f7-b5e5-97f2779b4ddd'::uuid, 'eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'Quelle qualité caractérise ses dialogues ?', 'mcq', '["Une langue parlée d’une efficacité redoutable","Un style précieux","Des tirades en vers","Un vocabulaire savant"]'::jsonb, 0, 'Elle annonce, par le décalage, le théâtre de l’absurde.', 4),
    ('6f7c8f3f-487e-5933-a75c-31f28c491977'::uuid, 'eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'À quelle époque Courteline écrit-il ?', 'mcq', '["À la fin du XIXe et au début du XXe siècle","Au XVIIe siècle","Sous la Révolution","Après 1945"]'::jsonb, 0, 'Il vit de 1858 à 1929.', 5),
    ('cfcfc68e-eb70-5e69-82b4-0354329a97d2'::uuid, 'eace602f-fbd6-5a34-be0a-2317372cb873'::uuid, 'Les pièces de Courteline sont de longues comédies de mœurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont pour la plupart des saynètes et des pièces en un ou deux actes.', 6),
    ('1c3a7599-2d09-5787-b9a5-ee48dc23eec8'::uuid, 'b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'De quoi Joseph K. est-il accusé ?', 'mcq', '["On ne le lui dira jamais","De détournement de fonds","De meurtre","De trahison"]'::jsonb, 0, 'L’absence d’accusation est le cœur du roman.', 1),
    ('8e58d2eb-acd6-5487-a665-ecac9ad14357'::uuid, 'b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'Que se passe-t-il après son arrestation ?', 'mcq', '["Il reste libre et continue son travail tout en étant « en procès »","Il est emprisonné","Il fuit à l’étranger","Il est jugé aussitôt"]'::jsonb, 0, 'La justice s’installe dans sa vie sans jamais l’enfermer.', 2),
    ('c16ab55b-8f0a-5785-b1d7-f48dec606914'::uuid, 'b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'Que raconte la parabole « Devant la Loi » ?', 'mcq', '["Un homme attend toute sa vie devant une porte ouverte pour lui seul","Un juge corrompu","Un innocent gracié","Un procès public"]'::jsonb, 0, 'L’aumônier la lui raconte dans la cathédrale.', 3),
    ('681cb9bd-140b-51bb-8f50-ada88a0b1013'::uuid, 'b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Deux hommes emmènent K. dans une carrière et le tuent","K. est acquitté","Le procès est annulé","K. s’enfuit"]'::jsonb, 0, '« Comme un chien ! » sont ses derniers mots.', 4),
    ('a0aed8ac-b347-5ad2-8091-9f168b6f3908'::uuid, 'b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'Comment le roman a-t-il été publié ?', 'mcq', '["Par Max Brod, en 1925, contre la volonté de Kafka","Par Kafka lui-même en 1914","En feuilleton dans un journal","Il n’a jamais été publié intégralement"]'::jsonb, 0, 'Kafka avait demandé que ses manuscrits soient brûlés.', 5),
    ('043f2dee-8750-5e21-874c-d92c6d9a3142'::uuid, 'b4e14d10-f060-5d3b-a621-13fa6cc40497'::uuid, 'Le roman est achevé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est inachevé : l’ordre des chapitres reste discuté.', 6),
    ('d5ce3eca-3a9f-5097-bf3d-ced687266857'::uuid, 'eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Qui est Abel Tiffauges ?', 'mcq', '["Un garagiste solitaire persuadé que le monde lui envoie des signes","Un officier allemand","Un instituteur breton","Un médecin militaire"]'::jsonb, 0, 'Il tient un journal intitulé « Écrits sinistres ».', 1),
    ('af0b3002-a523-57ad-a72e-f9159e7ce55b'::uuid, 'eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Que devient-il en Prusse-Orientale ?', 'mcq', '["Rabatteur d’enfants pour une école d’élite nazie","Interprète","Ouvrier agricole","Soldat de la Wehrmacht"]'::jsonb, 0, 'Il parcourt les campagnes pour y recruter des garçons.', 2),
    ('7ff55640-baad-581a-becb-445264555fcb'::uuid, 'eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Quel mythe donne son titre au roman ?', 'mcq', '["La ballade du Roi des Aulnes de Goethe","Le mythe d’Œdipe","La légende de saint Christophe seule","Le mythe de Prométhée"]'::jsonb, 0, 'Un père y porte son enfant qu’un roi surnaturel vient prendre.', 3),
    ('4a6573f6-ecff-566b-84d1-907f8f999f90'::uuid, 'eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Qu’est-ce que la « phorie » chez Tournier ?', 'mcq', '["Le fait de porter, à la fois amour et capture","La fuite en avant","La chasse au gros gibier","L’écriture d’un journal"]'::jsonb, 0, 'C’est l’ambivalence centrale du livre.', 4),
    ('b0da44c9-1262-5eb6-8542-0376587bd375'::uuid, 'eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Comment le roman se termine-t-il ?', 'mcq', '["Tiffauges porte un enfant juif rescapé et s’enfonce dans le marais","Il est fusillé","Il retourne en France","Il devient directeur de l’école"]'::jsonb, 0, 'La fin renverse le sens de toute sa trajectoire.', 5),
    ('18f77857-4e20-5834-87b0-50a7e15179b2'::uuid, 'eb4f0cc1-cd48-57c2-a5da-86ea3a36ce3c'::uuid, 'Le roman a obtenu le prix Goncourt.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'En 1970, et à l’unanimité du jury.', 6),
    ('70f680cf-7d5d-5029-a506-91dd732bf32c'::uuid, '688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'Que dit-on au roi dès le début de la pièce ?', 'mcq', '["Qu’il mourra à la fin du spectacle","Qu’il a perdu la guerre","Qu’il doit abdiquer","Qu’il est guéri"]'::jsonb, 0, 'La durée de la pièce est celle de l’agonie.', 1),
    ('20ff371c-7bb6-502c-be99-832c959044cc'::uuid, '688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'Quel rôle joue la reine Marguerite ?', 'mcq', '["Elle l’aide lucidement à se détacher","Elle lui promet la guérison","Elle complote contre lui","Elle refuse de lui parler"]'::jsonb, 0, 'Marie, la seconde reine, le retient au contraire dans l’illusion.', 2),
    ('ca652cb6-b186-56b7-8bbc-db1ae6824527'::uuid, '688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'Que devient le royaume au fil de la pièce ?', 'mcq', '["Il se fissure et rétrécit","Il s’étend","Il est envahi","Il reste inchangé"]'::jsonb, 0, 'Le décor accompagne la disparition du roi.', 3),
    ('ddab8c84-a960-52f2-a142-f7c24fa45f9b'::uuid, '688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'Que demande le roi ?', 'mcq', '["Qu’on lui apprenne à mourir","Qu’on le sauve par la médecine","Qu’on lui rende son armée","Qu’on rappelle Marie"]'::jsonb, 0, 'C’est le sujet même de la pièce : on meurt sans avoir appris.', 4),
    ('44cc7357-aa1c-5850-9e12-e0410f32190e'::uuid, '688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Marguerite le guide pas à pas, tout disparaît, le roi s’efface","Le roi guérit","Le roi abdique et part","Le rideau tombe sur une révolte"]'::jsonb, 0, 'La disparition est progressive et méthodique.', 5),
    ('fae7d703-d0a2-5276-921c-0742eb8db9b7'::uuid, '688e9ea9-4ebe-5994-bd60-c16949680d67'::uuid, 'La pièce abandonne tout comique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le rire persiste, grinçant, jusque dans l’agonie.', 6),
    ('a6d5e6e3-2ab7-5781-917c-46899d0ccb70'::uuid, 'aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'Comment le récit antique est-il introduit ?', 'mcq', '["Par la découverte d’une tombe et d’un papyrus traduit","Par un rêve","Par une lettre retrouvée","Sans cadre : le récit commence directement"]'::jsonb, 0, 'Un lord anglais et le savant Rumphius font la découverte.', 1),
    ('4605c6d9-5255-512d-ab39-11d4528a5fff'::uuid, 'aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'Qui est Tahoser ?', 'mcq', '["La fille d’un grand prêtre, aimée du pharaon","Une esclave hébraïque","La sœur de Moïse","Une reine étrangère"]'::jsonb, 0, 'Elle aime Poëri, qui en aime une autre.', 2),
    ('474b9f98-6350-5e2c-9b01-5eb4cf78c250'::uuid, 'aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'Quel épisode biblique traverse le roman ?', 'mcq', '["Les plaies d’Égypte et la fuite des Hébreux","Le déluge","La construction de la tour de Babel","Le règne de Salomon"]'::jsonb, 0, 'L’armée du pharaon est engloutie dans la mer Rouge.', 3),
    ('01d67c57-352d-5c07-be0e-c85d5011e33b'::uuid, 'aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'Sur quoi Gautier appuie-t-il ses descriptions ?', 'mcq', '["Les travaux des égyptologues de son temps","Son propre voyage en Égypte","La Bible seule","Son imagination pure"]'::jsonb, 0, 'L’exactitude archéologique fait partie du projet.', 4),
    ('5bf47330-9b17-5f51-a461-790f3b61e85d'::uuid, 'aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'À quelle doctrine esthétique Gautier se rattache-t-il ?', 'mcq', '["L’art pour l’art","Le naturalisme","Le réalisme social","Le symbolisme"]'::jsonb, 0, 'La beauté visuelle y prime sur la psychologie.', 5),
    ('455b6521-c60a-5b78-8016-bdc1a4aa54de'::uuid, 'aa030428-3dce-5cab-b6f0-6005157f159e'::uuid, 'Le roman est écrit à la première personne par la momie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le récit antique est présenté comme la traduction d’un papyrus.', 6),
    ('ff586e0b-42b3-5dc9-a8ff-7223875d560e'::uuid, 'adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Comment Aragon présente-t-il ce recueil ?', 'mcq', '["Comme une autobiographie en vers","Comme un roman","Comme un essai politique","Comme un journal de guerre"]'::jsonb, 0, 'Le titre indique qu’une vie ne se referme pas.', 1),
    ('e132816b-eda3-5a99-b91d-018066b789ff'::uuid, 'adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Quel secret de naissance le recueil évoque-t-il ?', 'mcq', '["Aragon a été élevé en croyant que sa mère était sa sœur","Il était orphelin","Il ignorait sa nationalité","Il avait un frère jumeau"]'::jsonb, 0, 'La révélation a marqué toute son œuvre.', 2),
    ('7e6f54e0-3c45-58a4-b3c0-d850114c61d5'::uuid, 'adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Quelle particularité formelle Aragon revendique-t-il ?', 'mcq', '["Le retour de la rime, que les modernes avaient abandonnée","La suppression de la ponctuation","Le vers libre exclusif","Le poème en prose"]'::jsonb, 0, 'La rime est selon lui l’instrument d’une poésie populaire et chantable.', 3),
    ('dbd6fc26-52c3-5ddb-b97e-655702730a65'::uuid, 'adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Quel poème du recueil évoque le groupe Manouchian ?', 'mcq', '["Strophes pour se souvenir","Le Conscrit des cent villages","Les Yeux d’Elsa","La Rose et le Réséda"]'::jsonb, 0, 'Il a été mis en musique par Léo Ferré.', 4),
    ('b13229ba-add1-583e-9ad3-567cdce22f6d'::uuid, 'adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Quel événement politique traverse le recueil ?', 'mcq', '["Les doutes de 1956, après le rapport Khrouchtchev","La guerre d’Algérie seule","Mai 68","La Libération"]'::jsonb, 0, 'L’engagement communiste y côtoie l’inquiétude.', 5),
    ('82baebc1-46e4-5758-a13b-e791d2f0ced1'::uuid, 'adc8b533-e343-5b10-9abc-49e853a489ef'::uuid, 'Les poèmes d’Aragon ont été largement mis en musique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ferré, Ferrat et Brassens en ont fait des chansons connues de tous.', 6),
    ('901c0c0e-85cd-5230-8a15-657489b0e59e'::uuid, '834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Que symbolisent le rouge et le noir ?', 'mcq', '["L’armée et l’Église, deux voies d’ascension","Le sang et la mort","La révolution et la royauté","L’amour et la haine"]'::jsonb, 0, 'Julien serait officier sous Napoléon ; il sera séminariste.', 1),
    ('f98bc73c-828b-56bf-a093-4ba0fc9889b8'::uuid, '834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Quelle est l’origine sociale de Julien ?', 'mcq', '["Fils d’un charpentier de Verrières","Fils d’un notaire","Orphelin recueilli par l’Église","Fils d’un officier de l’Empire"]'::jsonb, 0, 'Son orgueil de classe explique ses conduites.', 2),
    ('94841655-e09b-533a-9af5-3dc869e7a809'::uuid, '834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Qu’est-ce qui ruine sa réussite parisienne ?', 'mcq', '["Une lettre de Madame de Rênal, dictée par son confesseur","Un duel","Une dette de jeu","Une dénonciation de Mathilde"]'::jsonb, 0, 'Elle le dénonce comme séducteur ambitieux.', 3),
    ('db707e1f-f443-520f-9e68-742e3c6d8590'::uuid, '834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Où Julien tire-t-il sur Madame de Rênal ?', 'mcq', '["Dans l’église de Verrières, pendant la messe","Chez les La Mole","Dans le jardin de Vergy","Au séminaire"]'::jsonb, 0, 'Le lieu donne au geste sa portée de scandale.', 4),
    ('592a8ef9-7fb9-5daa-9c09-c2a82750b5ad'::uuid, '834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Que fait Julien à son procès ?', 'mcq', '["Il accuse la société de le condamner comme paysan sorti de sa classe","Il plaide la folie","Il nie les faits","Il implore la clémence"]'::jsonb, 0, 'C’est le sommet politique du roman.', 5),
    ('cbf9a2f4-eeef-5cf9-91b4-b854a54b85bd'::uuid, '834217de-4c0c-5f1e-821d-4007e5c184bc'::uuid, 'Le roman est sous-titré « Chronique de 1830 ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il paraît l’année même de la révolution de Juillet.', 6),
    ('46518470-6e58-5e1f-8767-7841d59e885b'::uuid, '6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Qui est Tartuffe ?', 'mcq', '["Un faux dévot recueilli par Orgon","Le confesseur de la famille","Le frère d’Elmire","Un notaire"]'::jsonb, 0, 'Sa piété ostentatoire aveugle Orgon.', 1),
    ('4b716495-afb2-583b-998c-b7c6fe1a4738'::uuid, '6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Comment Elmire démasque-t-elle Tartuffe ?', 'mcq', '["En cachant Orgon sous une table pendant qu’il la courtise","En lisant ses lettres","En le dénonçant au roi","En le faisant suivre"]'::jsonb, 0, 'La scène est l’une des plus célèbres du théâtre français.', 2),
    ('c4c6bfbd-56e4-53a0-a7f6-ee564f9f1400'::uuid, '6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Qu’a imprudemment donné Orgon à Tartuffe ?', 'mcq', '["Une donation de ses biens et une cassette compromettante","Sa maison de campagne seulement","Une charge de notaire","Son titre de noblesse"]'::jsonb, 0, 'C’est ce qui permet à Tartuffe de faire expulser la famille.', 3),
    ('e405c83c-fbe7-5028-8946-95b6dddcf008'::uuid, '6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Comment la pièce se dénoue-t-elle ?', 'mcq', '["Un exempt du roi arrête Tartuffe","Orgon tue Tartuffe","Tartuffe s’enfuit de lui-même","La famille quitte Paris"]'::jsonb, 0, 'Un hommage obligé au prince, et une fin fragile.', 4),
    ('e9378462-b305-57a3-9f49-a302bd854b3d'::uuid, '6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Combien de temps la pièce est-elle restée interdite ?', 'mcq', '["Cinq ans, de 1664 à 1669","Un an","Dix ans","Elle n’a jamais été interdite"]'::jsonb, 0, 'La cabale des dévots y voyait une attaque contre la religion.', 5),
    ('f3919f00-b53d-5913-91d8-5d8b66d449fc'::uuid, '6ee829e5-6fa7-5a80-a724-468ea6e44478'::uuid, 'Tartuffe apparaît dès la première scène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’entre qu’au troisième acte, après avoir été construit par les paroles des autres.', 6)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 263 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 263 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
